    ('221921b0-a4fb-5d68-95c5-e3b51778a8a6'::uuid, 'Semestre 1 — Introduction au droit et droit des personnes'),
    ('9b0b0865-7401-5474-9936-49e10de45bfa'::uuid, 'Semestre 1 — Introduction au droit et droit des personnes'),
    ('5d2f84c3-5cc8-5a25-8450-ff2f95d41f9c'::uuid, 'Semestre 1 — Introduction au droit et droit des personnes'),
    ('3cdf7907-53b0-5cb2-9e1f-40cad333bc09'::uuid, 'Semestre 1 — Introduction au droit et droit des personnes'),
    ('83aa1885-e347-5f25-95c6-f2472a3a9f7b'::uuid, 'Semestre 1 — Introduction au droit et droit des personnes'),
    ('7e089999-7a09-5ff9-b44b-6eb1e7705578'::uuid, 'Semestre 1 — Introduction au droit et droit des personnes'),
    ('a8139e8e-396c-5b28-8b2b-ebfd7067b7bb'::uuid, 'Semestre 2 — Droit de la famille'),
