  ) AS v(id, theme)
 WHERE c.id = v.id AND c.theme IS DISTINCT FROM v.theme;

-- 2. Leçons ----------------------------------------------------------------
INSERT INTO public.lessons (id, chapter_id, title, content, position) VALUES
  ('d42f5e39-1af4-58af-a9b2-b19bce2c2191', '47d777f5-7d7a-5bce-9993-ae1ba024bda1', 'Qu’est-ce qu’une règle de droit ?', E'Le **droit objectif** est l’ensemble des règles qui organisent la vie en société et dont le respect est garanti par la contrainte de l’État. Le **droit subjectif**, lui, est la prérogative qu’une règle reconnaît à une personne : le droit de propriété, le droit d’obtenir le paiement d’une créance. Le droit objectif est la règle ; le droit subjectif est ce que la règle me donne.\n\n## Les caractères de la règle de droit\nUne règle de droit se reconnaît à cinq traits.\n\n| Caractère | Signification | Illustration |\n| Générale | Elle vise une catégorie de personnes, pas un individu | Tout conducteur doit respecter la limitation de vitesse |\n| Abstraite | Elle prévoit une situation type, pas un cas particulier | « Celui qui cause un dommage doit le réparer » |\n| Permanente | Elle dure jusqu’à son abrogation | Le Code civil de 1804 est toujours en vigueur |\n| Obligatoire | Nul ne peut s’y soustraire à sa guise | On ne choisit pas d’obéir ou non |\n| Sanctionnée | L’État peut contraindre à la respecter | Dommages et intérêts, amende, exécution forcée |\n\nLa sanction distingue la règle de droit de la règle morale ou religieuse : seule la première est assortie d’une contrainte étatique. Les deux se recoupent pourtant souvent (ne pas tuer, ne pas voler) et le droit s’inspire de la morale sans s’y confondre.\n\n## Droit public et droit privé\nLe **droit privé** régit les rapports entre particuliers (droit civil, droit commercial, droit du travail). Le **droit public** régit l’organisation de l’État et ses rapports avec les particuliers (droit constitutionnel, droit administratif). Le droit civil est le « droit commun » du droit privé : il fournit les règles générales qui s’appliquent à défaut de règle spéciale.\n\n## Règles impératives et règles supplétives\nUne règle **impérative** s’impose : on ne peut y déroger. L’**article 6 du Code civil** interdit de déroger par des conventions particulières aux lois qui intéressent l’ordre public et les bonnes mœurs. Une règle **supplétive** ne s’applique qu’à défaut de volonté contraire des parties : les époux peuvent par exemple écarter le régime légal de la communauté réduite aux acquêts en choisissant un autre régime.\n\n## L’application de la loi dans le temps et le rôle du juge\nSelon l’**article 2 du Code civil**, la loi ne dispose que pour l’avenir : elle n’a point d’effet rétroactif. Le principe est de valeur législative en matière civile, le législateur pouvant y déroger. Quant au juge, l’**article 4** lui interdit de refuser de juger sous prétexte du silence, de l’obscurité ou de l’insuffisance de la loi, sous peine de déni de justice. L’**article 5** lui défend de statuer par voie de disposition générale et réglementaire : il tranche un litige, il ne légifère pas.\n\n> Une règle de droit est générale, abstraite et obligatoire, et sa violation est sanctionnée par l’État ; le droit objectif est la règle, le droit subjectif la prérogative qu’elle confère.\n\n## Les droits subjectifs\nOn classe les droits subjectifs en droits **patrimoniaux** (évaluables en argent : droits réels comme la propriété, droits personnels ou créances) et **extrapatrimoniaux** (attachés à la personne : droit au respect de la vie privée, droit au nom). Les premiers sont en principe cessibles et transmissibles ; les seconds sont hors commerce.\n\n## Exemple travaillé\nUne loi nouvelle, entrée en vigueur le 1er mars, interdit un type de clause dans les contrats de location. Un bailleur soutient que la clause qu’il avait insérée dans un bail signé en janvier est donc nulle. A-t-il raison ?\nMajeure : la loi ne dispose que pour l’avenir et n’a pas d’effet rétroactif (article 2 du Code civil), sauf disposition contraire expresse et sous réserve des lois impératives d’application immédiate aux effets futurs d’un contrat en cours.\nMineure : le bail a été conclu en janvier, avant l’entrée en vigueur de la loi, et rien n’indique que la loi soit rétroactive.\nConclusion : la clause, valable à sa conclusion, n’est pas atteinte par la loi nouvelle ; le bailleur a tort.', 1),
  ('5190b799-01de-58bc-af08-f06aedeb7a5b', '221921b0-a4fb-5d68-95c5-e3b51778a8a6', 'D’où vient la règle de droit, et laquelle l’emporte ?', E'Les **sources du droit** sont les procédés par lesquels naissent les règles de droit. En droit français, on distingue les sources internes (Constitution, loi, règlement, jurisprudence, coutume) et les sources supranationales (traités internationaux, droit de l’Union européenne, Convention européenne des droits de l’homme). Ces règles ne sont pas toutes de même rang : elles forment une **hiérarchie des normes** (pyramide de Kelsen), où chaque norme tire sa validité de celle qui lui est supérieure.\n\n## La Constitution et le bloc de constitutionnalité\nAu sommet de l’ordre interne, la **Constitution du 4 octobre 1958**. Le Conseil constitutionnel y a rattaché un **bloc de constitutionnalité** : le texte de 1958, la Déclaration des droits de l’homme et du citoyen de 1789, le Préambule de la Constitution de 1946 et la Charte de l’environnement de 2004. Une loi contraire à ce bloc peut être censurée.\n\n## Traités et droit de l’Union européenne\nL’**article 55 de la Constitution** donne aux traités régulièrement ratifiés une autorité supérieure à celle des lois, sous réserve de leur application par l’autre partie (réciprocité). Le droit de l’Union a lui-même la primauté sur le droit national : les **règlements** sont directement applicables, tandis que les **directives** doivent être transposées par chaque État. La Cour de cassation (chambre mixte, 24 mai 1975, Jacques Vabre) et le Conseil d’État (20 octobre 1989, Nicolo) ont admis qu’un juge peut écarter une loi, même postérieure, contraire à un traité : c’est le **contrôle de conventionnalité**. Le Conseil d’État maintient en revanche la supériorité de la Constitution sur les traités dans l’ordre interne (arrêt Sarran, 30 octobre 1998).\n\n## La loi et le règlement\nLa loi est votée par le Parlement ; son domaine est fixé par l’**article 34 de la Constitution** (droits civiques, état et capacité des personnes, régimes matrimoniaux, successions…). Tout le reste relève du pouvoir réglementaire (article 37) : décrets du Président de la République ou du Premier ministre, arrêtés des ministres et des préfets. Le règlement est inférieur à la loi : un décret contraire à la loi est illégal et peut être annulé par le juge administratif (recours pour excès de pouvoir). Le Gouvernement peut aussi, sur habilitation, prendre des ordonnances (article 38) ; elles deviennent des actes de valeur législative une fois ratifiées.\n\n| Rang | Norme | Qui la fait ? |\n| 1 | Constitution (bloc de constitutionnalité) | Pouvoir constituant |\n| 2 | Traités et droit de l’Union | États, institutions européennes |\n| 3 | Loi | Parlement |\n| 4 | Règlement | Gouvernement, administration |\n\n## Les sources non écrites\nLa **jurisprudence** est l’ensemble des décisions des juridictions. Elle n’est pas formellement une source du droit (le juge ne peut statuer par voie générale), mais, par la répétition de ses solutions, notamment celles de la Cour de cassation, elle précise et comble la loi. La coutume est une pratique ancienne ressentie comme obligatoire ; elle est en recul, mais subsiste en droit commercial. La doctrine (écrits des universitaires) n’a aucune force obligatoire, mais elle influence juges et législateurs.\n\n## Le contrôle de constitutionnalité\nLe Conseil constitutionnel contrôle les lois avant leur promulgation (contrôle a priori) et, depuis 2010, sur renvoi d’une juridiction, après leur promulgation grâce à la **question prioritaire de constitutionnalité** (article 61-1).\n\n> La norme inférieure doit respecter la norme supérieure : Constitution, puis traités, puis lois, puis règlements ; la jurisprudence en précise l’application.\n\n## Exemple travaillé\nUn décret ajoute une obligation que la loi ne prévoit pas et prive un citoyen d’un droit que cette loi lui accorde. Le citoyen peut-il obtenir qu’on écarte ce décret ?\nMajeure : un règlement doit respecter la loi, norme supérieure ; un acte réglementaire contraire à la loi est illégal.\nMineure : le décret retire un droit que la loi accorde expressément.\nConclusion : le décret est illégal ; le citoyen peut demander son annulation au juge administratif par un recours pour excès de pouvoir, ou en exciper de l’illégalité devant tout juge saisi du litige.', 1),
  ('e6459575-96a5-56da-b842-a3270510800a', '9b0b0865-7401-5474-9936-49e10de45bfa', 'Prouver un droit : charge, objet et modes de preuve', E'Avoir un droit ne suffit pas : encore faut-il pouvoir le prouver. Un droit contesté et non prouvé est, en pratique, un droit qui n’existe pas. La preuve est réglée, depuis l’ordonnance du 10 février 2016 (entrée en vigueur le 1er octobre 2016), par les articles 1353 et suivants du Code civil, et, pour la procédure, par l’article 9 du Code de procédure civile.\n\n## La charge de la preuve\nSelon l’**article 1353** du Code civil, celui qui réclame l’exécution d’une obligation doit la prouver ; réciproquement, celui qui se prétend libéré doit justifier le paiement ou le fait qui a produit l’extinction de son obligation. On résume : **le demandeur prouve** ce qu’il avance, puis le défendeur prouve ce qu’il oppose. Un créancier prouve donc l’existence de la dette ; le débiteur prouve qu’il l’a payée.\n\n## L’objet de la preuve : acte ou fait juridique\nLa distinction fondamentale est celle de l’**acte juridique** (manifestation de volonté destinée à produire des effets de droit : un contrat, un testament) et du fait juridique (événement auquel la loi attache des effets, volontaire ou non : un accident, une naissance, un dommage).\n\n| | Acte juridique | Fait juridique |\n| Exemple | Un contrat de vente | Un accident de la circulation |\n| Régime | Preuve réglementée | Preuve libre (art. 1358) |\n| Moyens | Écrit exigé au-delà d’un seuil | Tous moyens : témoins, photos, expertise |\n\nAu-delà de **1 500 euros** (seuil fixé par décret), un acte juridique doit être prouvé par écrit (**article 1359**). En dessous, ou entre commerçants (preuve libre en matière commerciale), on peut recourir à d’autres moyens. L’écrit n’est pas toujours possible : en cas d’impossibilité matérielle ou morale de se procurer un écrit, la preuve redevient libre.\n\n## Les modes de preuve\n- L’écrit : l’**acte authentique**, reçu par un officier public (notaire, commissaire de justice), fait foi jusqu’à inscription de faux ; l’acte sous signature privée suppose la signature des parties. L’**écrit électronique** a la même force probante que l’écrit papier si l’auteur est identifié et si l’intégrité est garantie (article 1366).\n- Le témoignage, admissible pour les faits ou lorsque la preuve est libre ;\n- La présomption, conséquence que la loi ou le juge tire d’un fait connu pour un fait inconnu : elle est simple (preuve contraire possible) ou **irréfragable** (aucune preuve contraire) ;\n- L’aveu (article 1383), déclaration par laquelle une personne reconnaît pour vrai un fait de nature à produire contre elle des conséquences juridiques ;\n- Le serment, décisoire ou supplétoire.\n\n## Les règles à ne pas oublier\n**Nul ne peut se constituer de preuve à soi-même** (article 1363) : un courrier rédigé par vous seul ne prouve pas votre créance. Le **commencement de preuve par écrit** (article 1362) est un écrit émanant de celui qu’on veut opposer, qui rend vraisemblable le fait allégué ; il permet de le compléter par témoins ou présomptions. Enfin, la preuve doit être **loyale** : une preuve obtenue par un procédé déloyal (enregistrement clandestin, stratagème) est en principe irrecevable, même si, à titre exceptionnel, la jurisprudence admet qu’un juge l’examine lorsqu’elle est indispensable à l’exercice du droit à la preuve et proportionnée.\n\n> Celui qui réclame l’exécution d’une obligation la prouve ; les faits se prouvent par tous moyens, les actes au-delà de 1 500 euros par écrit.\n\n## Exemple travaillé\nUne personne prête 3 000 euros à un ami, sans écrit, et réclame le remboursement. Peut-elle prouver le prêt par témoins ?\nMajeure : un acte juridique portant sur une somme supérieure au seuil fixé par décret (1 500 euros) doit être prouvé par écrit (article 1359) et nul ne peut se constituer de preuve à soi-même (article 1363).\nMineure : le prêt de 3 000 euros est un acte juridique supérieur au seuil ; il n’existe aucun écrit.\nConclusion : la preuve testimoniale seule est irrecevable ; elle ne le serait pas s’il existait un commencement de preuve par écrit (par exemple un message de l’emprunteur reconnaissant la dette).', 1),
  ('041fcc9c-ce1d-5aa8-973f-3d4848518c28', '5d2f84c3-5cc8-5a25-8450-ff2f95d41f9c', 'Être une personne en droit : naissance, fin et droits de la personnalité', E'La **personnalité juridique** est l’aptitude à être titulaire de droits et assujetti à des obligations. Les êtres humains sont des **personnes physiques** ; tout être humain, sans exception, a la personnalité juridique : l’esclavage et la mort civile n’existent plus en droit français.\n\n## Le début de la personnalité\nEn principe, la personnalité juridique commence à la **naissance**, à condition que l’enfant naisse **vivant et viable**. Une exception, qui tient à l’adage **infans conceptus pro nato habetur quoties de commodis ejus agitur** (l’enfant conçu est considéré comme né chaque fois que son intérêt l’exige) : l’**article 906 du Code civil** permet de recevoir une donation ou un legs dès lors qu’on est **conçu**, à condition de naître viable. L’embryon n’est cependant pas une personne juridique ; il bénéficie du respect dû à l’être humain dès le commencement de sa vie (article 16).\n\n## La fin de la personnalité\nLa personnalité s’éteint à la **mort**, constatée par un médecin. Le droit organise le sort des personnes dont le décès n’est pas certain : l’**absence** (disparition inquiétante, article 112 et suivants) puis, après jugement, la déclaration d’absence ou de décès. Lorsque plusieurs personnes meurent dans le même événement sans qu’on sache laquelle est décédée la première, on parle de **commorientes** : aucune ne succède à l’autre.\n\n## Capacité de jouissance et capacité d’exercice\n- La **capacité de jouissance** est l’aptitude à être titulaire de droits. Elle appartient à toute personne et ne peut être retirée en bloc.\n- La **capacité d’exercice** est l’aptitude à exercer soi-même ses droits. Elle peut être limitée : les **incapables** (mineurs, majeurs protégés) sont protégés et représentés ou assistés.\n\n## Les droits de la personnalité\nChacun possède des droits attachés à sa personne : droit au respect de la vie privée (**article 9**), droit à l’image, droit à l’honneur, droit au nom, présomption d’innocence (article 9-1). Ces droits sont **extrapatrimoniaux** : ils ne se vendent pas, ne se prescrivent pas et ne se transmettent pas par succession (l’action en réparation, elle, peut être exercée dans certaines limites).\n\n## Le corps humain\nLe Code civil protège le corps (articles 16 et suivants, issus des lois de bioéthique de 1994).\n\n| Principe | Contenu |\n| Primauté de la personne (art. 16) | La loi assure le respect de l’être humain dès le commencement de sa vie |\n| Inviolabilité du corps (art. 16-1) | Le corps humain est inviolable |\n| Non-patrimonialité (art. 16-1) | Le corps, ses éléments et ses produits ne peuvent faire l’objet d’un droit patrimonial |\n| Consentement (art. 16-3) | Aucune atteinte au corps sans consentement, sauf nécessité médicale |\n| Gestation pour autrui (art. 16-7) | Toute convention de procréation ou de gestation pour le compte d’autrui est nulle |\n\nLe don d’organes est gratuit ; l’eugénisme et le clonage reproductif sont interdits.\n\n> Toute personne physique a la personnalité juridique de sa naissance (vivant et viable) à sa mort ; ses droits de la personnalité et son corps sont hors commerce.\n\n## Exemple travaillé\nUn testateur lègue un appartement à l’enfant que sa nièce porte, alors conçu. Il meurt le mois suivant ; l’enfant naît vivant et viable quelques mois plus tard. Le legs est-il valable ?\nMajeure : pour recevoir par testament, il suffit d’être conçu à l’époque du décès du testateur, le legs n’ayant d’effet que si l’enfant naît viable (article 906).\nMineure : l’enfant était conçu au décès du testateur et il naît vivant et viable.\nConclusion : le legs est valable ; l’enfant en est titulaire, représenté par ses parents.', 1),
  ('99a18fe9-3711-5b44-9b1b-50efc3923b1f', '3cdf7907-53b0-5cb2-9e1f-40cad333bc09', 'Identifier une personne : nom, prénoms, domicile, sexe et actes', E'L’état civil (ou état des personnes) désigne l’ensemble des éléments qui identifient une personne et la situent dans la société : son nom, ses prénoms, son domicile, son sexe, sa filiation, sa situation familiale. Il a trois caractères : il est **d’ordre public** (on ne dispose pas librement de son état), indivisible (on ne peut avoir un état différent selon les domaines) et **indisponible** (on ne peut ni le vendre ni y renoncer).\n\n## Le nom\nLe nom de famille identifie la personne et marque son appartenance familiale. Il obéit au principe d’**immutabilité** : on ne change pas de nom à sa guise, sauf cas prévus par la loi. Le nom de l’enfant dépend de sa filiation : lorsque la filiation est établie à l’égard des deux parents, ils peuvent choisir de lui donner le nom de l’un, de l’autre, ou leurs deux noms accolés, dans l’ordre qu’ils choisissent et dans la limite d’un nom de famille chacun.\n\nLa **loi du 2 mars 2022** relative au choix du nom issu de la filiation (en vigueur depuis le 1er juillet 2022) a assoupli ce régime : toute personne majeure peut, **une fois dans sa vie**, demander à l’officier de l’état civil, par simple déclaration, à porter le nom de son autre parent en l’ajoutant au sien ou en s’y substituant. Elle a aussi facilité le **nom d’usage** : celui dont on se sert dans la vie sociale (ajout, ou substitution du nom d’un autre parent), qui ne figure pas dans les actes d’état civil et ne modifie pas le nom officiel. Hors de ces cas, un changement de nom exige un motif légitime, apprécié dans le cadre d’une procédure administrative (décret).\n\n## Les prénoms\nLes prénoms sont choisis par les parents et déclarés à l’officier de l’état civil. Si le prénom est contraire à l’intérêt de l’enfant (ridicule, grotesque, ou de nature à lui nuire), l’officier d’état civil en avise le procureur de la République, qui peut saisir le juge aux affaires familiales. Depuis la loi du 18 novembre 2016, un changement de prénom se demande à l’officier de l’état civil, sur justification d’un intérêt légitime.\n\n## Le domicile\nLe **domicile** est le lieu du principal établissement d’une personne (article 102). Il se distingue de la résidence (lieu où l’on vit de fait, même provisoirement). On distingue aussi le **domicile légal** (celui que la loi impose : le mineur non émancipé est domicilié chez ses parents) et le **domicile élu** (choisi pour l’exécution d’un acte, par exemple chez son avocat ou son notaire). Le domicile détermine notamment le tribunal territorialement compétent.\n\n## Le sexe à l’état civil\nDepuis la loi du 18 novembre 2016, toute personne majeure ou mineure émancipée qui démontre que la mention de son sexe ne correspond pas à son apparence et à son comportement social peut en demander la modification, devant le tribunal judiciaire, **sans avoir à justifier d’un traitement médical** ni d’une opération.\n\n## Les actes de l’état civil\nLes **actes d’état civil** constatent les événements qui rythment la vie d’une personne : naissance, mariage, décès. L’acte de naissance est dressé sur déclaration dans les cinq jours de l’accouchement. Ils sont authentiques : établis par un officier public, ils font foi jusqu’à inscription de faux. Chaque acte peut recevoir des **mentions marginales** (reconnaissance, mariage, divorce) qui le mettent à jour. On en délivre des copies intégrales (à tout intéressé dans certains cas) ou des extraits. Une erreur matérielle se rectifie par décision de justice, ou, pour les erreurs purement matérielles, sur décision du procureur de la République.\n\n| Élément | Règle essentielle |\n| Nom | Immuable ; changement par motif légitime ou procédures spéciales (2022) |\n| Prénom | Choix des parents ; changement par déclaration en mairie |\n| Domicile | Lieu du principal établissement (art. 102) |\n| Actes | Authentiques ; mentions marginales ; rectification judiciaire |\n\n> L’état civil est d’ordre public, indisponible et indivisible ; il se prouve par des actes authentiques que seule la justice peut rectifier.\n\n## Exemple travaillé\nMadame Durand, majeure, souhaite porter le nom de sa mère, Martin, en l’ajoutant au sien. Doit-elle saisir un juge ?\nMajeure : depuis la loi du 2 mars 2022, toute personne majeure peut, par déclaration à l’officier de l’état civil, ajouter à son nom celui de son autre parent, une fois dans sa vie.\nMineure : Madame Durand est majeure et n’a jamais fait cette démarche.\nConclusion : elle n’a pas à saisir un juge ; une déclaration à l’officier de l’état civil suffit.', 1),
  ('bcb867f7-c9c9-5ff0-a6d9-b2390e21e1c6', '83aa1885-e347-5f25-95c6-f2472a3a9f7b', 'Protéger ceux qui ne peuvent agir seuls : mineurs et majeurs protégés', E'Une incapacité est une limitation de la capacité d’exercice, instituée pour protéger la personne (ou, rarement, pour sanctionner). L’incapable a la capacité de jouissance (il est titulaire de droits) mais ne peut pas toujours les exercer seul : il est **représenté** (quelqu’un agit à sa place) ou **assisté** (quelqu’un l’accompagne dans l’acte).\n\n## Le mineur\nEst mineure toute personne qui n’a pas atteint l’âge de **dix-huit ans** (article 414 : la majorité est fixée à 18 ans accomplis). Le mineur est en principe incapable d’exercice : il agit par l’intermédiaire de ses représentants légaux, ses parents (administration légale, article 382 et suivants), ou, à défaut, un tuteur. Les actes accomplis par le mineur sans représentation sont en principe nuls (nullité relative), mais une exception majeure existe : les **actes de la vie courante**, autorisés par la loi ou l’usage et conclus à des conditions normales, sont valables (article 1148). Un mineur peut ainsi acheter un ticket de bus ou une baguette.\n\n## L’émancipation\nLe mineur peut être **émancipé** dès l’âge de **seize ans**, par décision du juge des tutelles, sur demande de ses parents ou de l’un d’eux, lorsque de justes motifs le justifient (article 413-2). Il devient alors capable comme un majeur pour les actes de la vie civile, mais il reste mineur pour d’autres domaines : il ne peut pas se marier avant 18 ans, et l’exercice du commerce est subordonné à une autorisation du juge des tutelles.\n\n## Les majeurs protégés\nUn majeur dont les facultés sont altérées peut bénéficier d’une mesure de protection. L’**article 425** pose la condition : l’impossibilité de pourvoir seul à ses intérêts en raison d’une altération (médicalement constatée) de ses facultés mentales ou corporelles de nature à empêcher l’expression de sa volonté. Les principes directeurs sont ceux de **nécessité, de subsidiarité et de proportionnalité** (article 428) : la mesure n’est ordonnée que si elle est nécessaire, si une mesure moins contraignante ne suffit pas, et elle doit être individualisée.\n\n| Mesure | Nature | Pour qui ? |\n| Sauvegarde de justice | Protection temporaire et légère, sans représentation générale | Altération temporaire ou attente d’une mesure plus durable |\n| Curatelle | Assistance : le curateur assiste la personne pour les actes graves | Personne ayant besoin d’être conseillée ou contrôlée de manière continue |\n| Tutelle | Représentation : le tuteur agit à la place de la personne | Personne devant être représentée de manière continue |\n| Habilitation familiale | Représentation par un proche, sans juge permanent | Famille en mesure de protéger la personne |\n| Mandat de protection future | Mesure **anticipée**, choisie en toute conscience | Toute personne souhaitant organiser sa protection |\n\nL’**habilitation familiale** (ordonnance du 15 octobre 2015) permet à un proche (ascendant, descendant, frère ou sœur, conjoint, partenaire, concubin) d’être habilité par le juge à représenter la personne, sans la lourdeur d’une tutelle. Le **mandat de protection future** permet à chacun de désigner à l’avance la personne qui s’occupera de lui.\n\n## La réforme de 2019\nLa **loi du 23 mars 2019** (programmation et réforme pour la justice) a modernisé ce droit : elle a supprimé la possibilité pour le juge de priver de son droit de vote une personne sous tutelle, et a libéré le mariage et le PACS des majeurs protégés de l’autorisation du juge (la personne chargée de la protection est simplement informée, et peut s’y opposer) ; dans l’instance en divorce, le majeur en tutelle est désormais représenté par son tuteur sans autorisation préalable, tout en maintenant un contrôle pour les actes les plus graves. Elle a aussi simplifié la procédure et le contrôle des comptes.\n\n> Mineurs et majeurs protégés sont protégés par la représentation ou l’assistance ; toute mesure de protection est nécessaire, subsidiaire et proportionnée.\n\n## Exemple travaillé\nLéa, 17 ans, non émancipée, vend seule sa moto d’occasion 2 000 euros. Ses parents veulent faire annuler la vente. Peuvent-ils y parvenir ?\nMajeure : le mineur non émancipé est incapable d’exercice ; ses actes ne sont valables que s’ils sont des actes de la vie courante conclus à des conditions normales, sinon ils sont annulables pour incapacité.\nMineure : la vente d’une moto 2 000 euros n’est pas un acte courant ; Léa a agi seule, sans ses représentants.\nConclusion : l’acte est annulable (nullité relative) à la demande des parents, représentants légaux de Léa.', 1),
  ('154cd255-343a-5aea-ac07-bc84ebb2549c', '7e089999-7a09-5ff9-b44b-6eb1e7705578', 'Les groupements dotés de la personnalité juridique', E'Une **personne morale** est un groupement de personnes ou de biens doté de la **personnalité juridique** : il est lui-même titulaire de droits et d’obligations, distinct des membres qui le composent. C’est la personne morale, et non ses associés, qui contracte, possède, agit en justice et endosse les dettes.\n\n## Les grandes catégories\nOn distingue les personnes morales de droit public (l’État, les collectivités territoriales, les établissements publics) et celles de droit privé.\n\n| Catégorie | Exemples | But |\n| Sociétés | SARL, SAS, société anonyme | Partager les bénéfices ou profiter de l’économie réalisée |\n| Associations | Association loi du 1er juillet 1901 | But autre que le partage des bénéfices |\n| Syndicats | Syndicats de salariés (loi du 21 mars 1884) | Défense d’intérêts professionnels |\n| Fondations, GIE | Fondation, groupement d’intérêt économique | Mission d’intérêt général ou coopération |\n\nLa **société** est définie par l’**article 1832 du Code civil** : elle est instituée par deux ou plusieurs personnes (ou, dans les cas prévus par la loi, par une seule) qui conviennent d’affecter à une entreprise commune des biens ou leur industrie en vue de partager le bénéfice ou de profiter de l’économie qui pourra en résulter. Elle suppose des **apports**, la **recherche d’un bénéfice** et l’**affectio societatis** (la volonté de collaborer sur un pied d’égalité). L’**association**, définie par l’article 1er de la loi de 1901, est la convention par laquelle deux ou plusieurs personnes mettent en commun, d’une façon permanente, leurs connaissances ou leur activité dans un but autre que de partager des bénéfices.\n\n## Comment naît la personnalité morale ?\nElle s’acquiert selon le type de groupement : la société jouit de la personnalité morale à compter de son **immatriculation au registre du commerce et des sociétés** (article 1842) ; l’association est capable de contracter dès sa **déclaration en préfecture** et sa publication au Journal officiel (pour la pleine capacité). La jurisprudence reconnaît aussi la personnalité morale à tout groupement doté d’une possibilité d’expression collective pour la défense d’intérêts licites (Cass. civ. 2e, 28 janvier 1954, comité d’établissement de Saint-Chamond).\n\n## Les attributs de la personnalité morale\n- un nom (dénomination, raison sociale) ;\n- un siège social, équivalent du domicile ;\n- une nationalité ;\n- un patrimoine propre, distinct de celui des membres ;\n- la capacité d’agir en justice ;\n- des **organes** (gérant, président, conseil d’administration, assemblée générale) qui l’expriment, car la personne morale n’a pas de volonté propre.\n\nLa capacité de la personne morale est limitée par le **principe de spécialité** : elle ne peut agir que dans les limites de son objet, tel qu’il est défini par ses statuts, sauf pour les actes qui en sont l’accessoire.\n\n## Conséquences : le patrimoine séparé\nParce que la personne morale a un patrimoine propre, les créanciers de la société ne peuvent poursuivre les associés d’une SARL ou d’une société anonyme sur leurs biens personnels : leur responsabilité est limitée à leurs apports. La contrepartie est le contrôle des dirigeants, qui engagent leur responsabilité en cas de faute de gestion.\n\n## La fin de la personnalité morale\nLa personne morale disparaît par **dissolution** (arrivée du terme, réalisation de l’objet, décision des associés, décision judiciaire), suivie de la liquidation (paiement des dettes, répartition du solde).\n\n> La personne morale est un sujet de droit distinct de ses membres, avec son nom, son siège, son patrimoine et ses organes, dans la limite de son objet.\n\n## Exemple travaillé\nUne SARL ne peut pas payer son fournisseur. Celui-ci poursuit l’un des associés sur ses biens personnels. L’associé doit-il payer ?\nMajeure : la personne morale a un patrimoine distinct de celui de ses membres, et les associés d’une SARL ne répondent des dettes sociales que dans la limite de leurs apports.\nMineure : la dette est celle de la SARL, l’associé a déjà versé ses apports et n’a pas cautionné la dette.\nConclusion : le fournisseur ne peut saisir les biens personnels de l’associé ; il doit agir contre la société.', 1),
  ('439814fc-bc7c-5fc7-8376-fb9b80c36349', 'a8139e8e-396c-5b28-8b2b-ebfd7067b7bb', 'Trois façons de vivre en couple : mariage, PACS et concubinage', E'Le droit français reconnaît trois formes de vie de couple, qui n’offrent ni les mêmes droits ni les mêmes devoirs : le mariage, le pacte civil de solidarité (PACS) et le concubinage.\n\n## Le mariage\nDepuis la **loi du 17 mai 2013**, le mariage est contracté par deux personnes de sexe différent ou de même sexe (article 143). Ses conditions de fond sont les suivantes : un **âge minimal de dix-huit ans** (article 144), un **consentement** libre de chacun des époux (article 146), l’absence de bigamie (article 147) et d’inceste (articles 161 et suivants). La condition de forme est la célébration publique par l’officier de l’état civil, à la mairie, après publication des bans.\n\nLes époux se doivent mutuellement **respect, fidélité, secours et assistance** (article 212) et s’obligent à une communauté de vie (article 215). Ils contribuent aux charges du mariage selon leurs facultés (article 214). Chacun a le pouvoir de passer seul les contrats qui ont pour objet l’entretien du ménage ou l’éducation des enfants, et l’autre époux est alors solidairement tenu de la dette (article 220), sauf dépenses manifestement excessives. Le logement de la famille est protégé : aucun époux ne peut en disposer seul (article 215, alinéa 3).\n\nLes rapports patrimoniaux sont régis par le régime matrimonial. À défaut de contrat de mariage, les époux sont soumis au régime légal de la **communauté réduite aux acquêts** : les biens acquis pendant le mariage sont communs, les biens possédés avant ou reçus par donation ou succession restent propres. Ils peuvent choisir la séparation de biens, la participation aux acquêts ou la communauté universelle, devant notaire. Depuis la loi du 23 mars 2019, ils peuvent changer de régime par un acte notarié, sans attendre un délai de deux ans, l’homologation du juge n’étant plus nécessaire dans la plupart des cas.\n\n## Le PACS\nLe **PACS** est un contrat conclu par deux personnes physiques majeures, de sexe différent ou de même sexe, pour organiser leur vie commune (**article 515-1**, issu de la loi du 15 novembre 1999). Il est enregistré par déclaration conjointe devant l’officier de l’état civil (ou le notaire). Les partenaires s’apportent une **aide matérielle et une assistance réciproques** (article 515-4) et sont solidaires des dettes contractées pour les besoins de la vie courante. En l’absence de choix contraire, le régime est celui de la **séparation des patrimoines** (article 515-5). Le PACS prend fin par déclaration conjointe, décision unilatérale signifiée à l’autre, mariage ou décès d’un des partenaires.\n\n## Le concubinage\nLe concubinage est défini par l’**article 515-8** comme une union de fait, caractérisée par une vie commune présentant un caractère de stabilité et de continuité, entre deux personnes de sexe différent ou de même sexe qui vivent en couple. Il ne crée par lui-même aucun devoir entre concubins ; sa rupture est libre, sauf abus ou faute dommageable.\n\n| | Mariage | PACS | Concubinage |\n| Formalité | Célébration en mairie | Enregistrement | Aucune |\n| Devoirs | Fidélité, secours, assistance | Aide matérielle, assistance | Aucun |\n| Dettes ménagères | Solidarité | Solidarité | Aucune |\n| Héritage légal | Oui, le conjoint | Non (testament) | Non (testament) |\n| Rupture | Divorce | Déclaration ou signification | Libre |\n\n> Le mariage est le plus protecteur, le PACS un contrat souple de vie commune, le concubinage une simple situation de fait.\n\n## Exemple travaillé\nDeux concubins vivent ensemble depuis dix ans ; l’un décède sans testament. Son compagnon peut-il hériter ?\nMajeure : le concubin n’a pas la qualité d’héritier légal ; seuls les parents proches et le conjoint survivant (marié) succèdent, sauf testament.\nMineure : les deux compagnons n’étaient ni mariés ni pacsés et il n’y a pas de testament.\nConclusion : le concubin survivant n’hérite pas ; il aurait fallu un testament, voire un mariage.', 1),
  ('242b4966-2598-5f2f-bc89-164d46003032', '22ba73c2-51d6-5a21-a4ce-9e9c81d79a71', 'Les quatre cas de divorce et leurs effets', E'Le divorce est la dissolution du mariage du vivant des deux époux. Il se distingue de la séparation de corps, qui relâche le lien conjugal (fin du devoir de cohabitation) sans le rompre, et de l’annulation du mariage, qui sanctionne un vice originel. Le droit du divorce a été profondément remanié par la loi du 18 novembre 2016 (divorce par acte d’avocats) et par la **loi du 23 mars 2019**, entrée en application le 1er janvier 2021.\n\n## Les quatre cas de divorce\nL’**article 229** du Code civil énumère quatre cas.\n\n| Cas | Principe | Procédure |\n| Consentement mutuel | Les époux sont d’accord sur le principe et sur toutes les conséquences | Convention rédigée par **acte sous signature privée contresigné par avocats**, déposée au rang des minutes d’un notaire (**article 229-1**) ; pas de juge |\n| Acceptation du principe de la rupture | Les époux acceptent la rupture sans considération des faits | Devant le juge aux affaires familiales |\n| Altération définitive du lien conjugal | Cessation de la communauté de vie depuis **un an** (art. 238) | Devant le juge |\n| Faute | Violations graves ou renouvelées des devoirs et obligations du mariage rendant intolérable le maintien de la vie commune (art. 242) | Devant le juge |\n\nDepuis le 1er janvier 2017, le divorce par consentement mutuel peut ne pas passer devant un juge. Le juge reste compétent dans deux situations : lorsqu’un enfant mineur demande à être entendu par le juge, et lorsque l’un des époux est placé sous un régime de protection (tutelle, curatelle). Le divorce est alors définitif dès le dépôt de la convention chez le notaire, qui lui confère date certaine et force exécutoire.\n\n## La procédure contentieuse depuis 2021\nLa réforme de 2019 a **supprimé la phase de conciliation** préalable. La procédure s’ouvre désormais par une **assignation** devant le **juge aux affaires familiales** du tribunal judiciaire. Le demandeur n’est plus obligé d’indiquer le fondement de sa demande dans l’assignation ; les époux peuvent aussi présenter une demande conjointe. Une audience d’orientation et sur mesures provisoires permet au juge de statuer sur les mesures provisoires (résidence, pension, logement) et d’organiser la suite de la procédure. Le délai d’un an de séparation de l’article 238 s’apprécie en principe à la date de la demande (ou, lorsque la demande ne précise pas de motif, au prononcé du divorce).\n\n## Les effets du divorce\n- Entre les époux : le divorce met fin au devoir de fidélité et de secours. Le jugement prend effet dans les rapports patrimoniaux à la date de la **demande en divorce** (le juge peut, à la demande de l’un, reporter ces effets à la date de la cessation de la cohabitation et de la collaboration). Chacun perd en principe l’usage du nom de l’autre (article 264), sauf accord ou autorisation du juge.\n- **La prestation compensatoire** (**article 270**) : elle vise à compenser la **disparité** que la rupture du mariage crée dans les conditions de vie respectives des époux. Elle prend en principe la forme d’un **capital**, exceptionnellement d’une rente viagère.\n- Les enfants : le divorce est sans incidence sur l’autorité parentale, qui reste exercée conjointement. Il se règle aussi la résidence de l’enfant (chez l’un ou en alternance) et la contribution à son entretien (pension alimentaire).\n- Le régime matrimonial : liquidation et partage des biens communs, sous la direction d’un notaire.\n- Les dommages et intérêts : possibles pour les conséquences d’une particulière gravité (article 266) ou sur le fondement de la responsabilité civile en cas de faute.\n\n> Il existe quatre cas de divorce ; sans conciliation depuis 2021, la procédure s’ouvre par assignation, tandis que le divorce par consentement mutuel se fait par acte d’avocats, sans juge.\n\n## Exemple travaillé\nDeux époux, sans enfant, sont d’accord sur tout : partage des biens, absence de prestation compensatoire. Doivent-ils plaider devant le juge ?\nMajeure : le divorce par consentement mutuel est constaté par un acte sous signature privée contresigné par avocats et déposé chez un notaire (article 229-1), sans intervention du juge, sauf demande d’audition d’un enfant mineur ou protection de l’un des époux.\nMineure : les deux époux sont d’accord, sont majeurs capables, et n’ont pas d’enfant.\nConclusion : ils divorcent sans juge, par acte d’avocats déposé chez le notaire.', 1),
  ('1956ab56-ff54-51f1-8dfb-411f6130a387', 'f6f7b8fc-61a0-58fb-a7e8-37b27c9f0d4f', 'Établir, contester et faire reconnaître un lien de filiation', E'La filiation est le lien juridique qui unit un enfant à un parent. Depuis l’ordonnance du 4 juillet 2005, tous les enfants dont la filiation est légalement établie ont les mêmes droits et les mêmes devoirs dans leurs rapports avec leurs père et mère (**article 310**) : la distinction entre enfant légitime et naturel a disparu.\n\n## Les types de filiation\nLe Code civil distingue la filiation biologique (charnelle), la filiation adoptive et, depuis 2021, la filiation issue de l’assistance médicale à la procréation avec tiers donneur.\n\n## Établir la filiation à l’égard de la mère\nElle résulte de la **désignation de la mère dans l’acte de naissance** (**article 311-25**). Aucune démarche n’est nécessaire ; la mère n’a donc pas besoin de reconnaître son enfant pour être sa mère légale. L’accouchement dit « sous X » (article 326) est une dérogation reconnue : la mère peut demander que le secret de son admission et de son identité soit préservé.\n\n## Établir la filiation à l’égard du père\nElle peut s’établir de plusieurs façons.\n- La présomption de paternité (article 312) : l’enfant conçu ou né pendant le mariage a pour père le mari de sa mère.\n- La reconnaissance (article 316) : déclaration volontaire du père (ou de la mère) devant l’officier de l’état civil ou un notaire, avant ou après la naissance.\n- La possession d’état : faisceau de faits publics, paisibles et continus qui révèlent le lien (l’enfant porte le nom, est traité comme tel, est reconnu par l’entourage). Constatée par un acte de notoriété, elle établit la filiation.\n- L’action en recherche : action judiciaire en établissement de la filiation, notamment par expertise biologique.\n\n## La PMA et la loi du 2 août 2021\nLa **loi bioéthique du 2 août 2021** a ouvert l’assistance médicale à la procréation à toutes les femmes : couples de femmes et femmes non mariées seules (et non plus aux seuls couples hétérosexuels infertiles). Pour un couple de femmes, la filiation à l’égard de la femme qui n’accouche pas s’établit par la **reconnaissance conjointe anticipée**, faite devant notaire avant l’AMP (**article 342-11**) et remise à l’officier de l’état civil au moment de la déclaration de naissance. La loi a aussi créé un droit d’accès aux origines : l’enfant majeur né d’un don peut accéder à l’identité du donneur, qui doit y consentir au moment du don. La **gestation pour autrui** reste interdite (article 16-7).\n\n## L’adoption\n**L’adoption plénière** crée une filiation qui remplace la filiation d’origine : elle est irrévocable et concerne en principe les enfants de moins de quinze ans. **L’adoption simple** s’ajoute à la filiation d’origine, que l’adopté conserve ; elle est révocable pour motifs graves. La loi du 21 février 2022 a réformé l’adoption, notamment en l’ouvrant aux couples non mariés.\n\n## Contestation et prescription\nLa filiation légalement établie peut être contestée dans certaines limites : l’action se prescrit par **dix ans** à compter du jour où la personne a été privée de l’état qu’elle réclame, ou a commencé à jouir de l’état qui lui est contesté (**article 321**). Lorsque la possession d’état est conforme au titre et a duré au moins cinq ans, seuls l’enfant, l’un de ses parents ou celui qui se prétend le parent véritable peuvent agir (article 333). La preuve biologique est de droit en matière de filiation, sauf motif légitime de ne pas y procéder.\n\n| Moyen | Qui ? | Condition |\n| Désignation dans l’acte de naissance | Mère | Accouchement |\n| Présomption | Père, époux de la mère | Mariage |\n| Reconnaissance | Père ou mère | Volonté libre |\n| Possession d’état | Tout parent | Faits continus, constatés |\n| Reconnaissance conjointe anticipée | Femme qui n’accouche pas | AMP avec tiers donneur, devant notaire |\n\n> La filiation s’établit par la loi (désignation, présomption), la volonté (reconnaissance, adoption) ou les faits (possession d’état) ; tous les enfants sont égaux en droits.\n\n## Exemple travaillé\nUn homme non marié veut reconnaître l’enfant né de sa compagne, sans lien légal préexistant. Quelle démarche accomplir ?\nMajeure : en dehors du mariage, la filiation paternelle s’établit par une reconnaissance volontaire faite devant l’officier de l’état civil ou un notaire (article 316), avant ou après la naissance.\nMineure : l’homme n’est pas marié avec la mère et souhaite être le père juridique de l’enfant.\nConclusion : il doit effectuer une reconnaissance ; la filiation sera établie à son égard avec les effets qui s’y attachent.', 1),
  ('0c944ac0-b80c-5b04-a762-a986ac22b2b3', 'ded1c57d-2f5c-57e4-bf58-ec334c46c05a', 'Les droits et devoirs des parents envers leur enfant', E'L’autorité parentale est, selon l’**article 371-1** du Code civil, un ensemble de droits et de devoirs ayant pour finalité l’**intérêt de l’enfant**. Elle appartient aux parents jusqu’à la majorité ou l’émancipation de l’enfant, pour le protéger dans sa sécurité, sa santé et sa moralité, assurer son éducation et permettre son développement, dans le respect dû à sa personne. Le mot clé est intérêt de l’enfant : l’autorité parentale n’est pas un pouvoir mais une fonction, au service de l’enfant.\n\n## Une autorité exercée en commun\nDepuis la loi du 4 mars 2002, l’autorité parentale est **exercée en commun** par les deux parents (article 372), qu’ils soient mariés, pacsés, concubins ou séparés. La séparation des parents est sans incidence sur les règles de dévolution de l’exercice de l’autorité parentale (article 373-2) : chacun maintient des relations personnelles avec l’enfant et respecte les liens de l’autre.\n\nÀ l’égard des tiers de bonne foi, chaque parent est réputé agir avec l’accord de l’autre lorsqu’il fait seul un **acte usuel** de l’autorité parentale (article 372-2) : inscrire l’enfant à une activité, l’emmener chez le médecin pour des soins courants. Les décisions **importantes** (changement d’établissement scolaire, opération non urgente, changement de religion, déménagement susceptible d’affecter les droits de l’autre) requièrent l’accord des deux parents.\n\n## Le contenu de l’autorité parentale\n- Le devoir de protection et d’éducation : santé, scolarité, moralité, surveillance.\n- Le droit de garde et le choix de la résidence : la résidence de l’enfant peut être fixée chez l’un des parents ou en **alternance** (article 373-2-9).\n- La contribution à l’entretien et à l’éducation (article 371-2) : chacun contribue selon ses ressources, par une **pension alimentaire** lorsque l’enfant ne vit pas avec lui, et cette obligation peut subsister après la majorité tant que l’enfant n’est pas autonome.\n- L’administration légale (article 382 et suivants) : les parents gèrent les biens de l’enfant mineur, avec contrôle du juge des tutelles pour les actes graves de disposition.\n- Le droit de l’enfant d’être entendu par le juge dans les procédures qui le concernent (article 388-1).\n\n## L’autorité parentale sans violences\nLa **loi du 10 juillet 2019** a ajouté à l’article 371-1 : l’autorité parentale s’exerce sans violences physiques ou psychologiques. Les violences éducatives dites « ordinaires » n’ont donc aucune justification légale, et le droit de correction n’existe plus.\n\n## Quand les choses se compliquent\nLorsque les parents sont séparés, le juge aux affaires familiales fixe la résidence de l’enfant et les modalités de son entretien. Il peut confier l’exercice de l’autorité parentale à un seul parent (**exercice unilatéral**) si l’intérêt de l’enfant l’exige (article 373-2-1) ; l’autre parent conserve alors un droit de visite et d’hébergement, sauf motifs graves, ainsi qu’un droit de surveillance. En cas de danger pour l’enfant (santé, sécurité, moralité, éducation compromise), le **juge des enfants** peut ordonner une mesure d’assistance éducative (article 375). Dans les cas les plus graves (condamnation pour crime ou délit commis sur l’enfant, par exemple), le **retrait de l’autorité parentale** peut être prononcé (articles 378 et suivants). Les parents peuvent aussi déléguer l’exercice de l’autorité, volontairement ou par décision judiciaire.\n\n| Acte | Qui décide ? | Exemple |\n| Acte usuel | Un seul parent suffit | Rendez-vous chez le médecin pour un rhume |\n| Acte important | Accord des deux parents | Changement d’école, opération non urgente |\n\n> L’autorité parentale est exercée en commun, dans l’intérêt de l’enfant et sans violences ; la séparation des parents n’en change pas le principe.\n\n## Exemple travaillé\nAprès leur séparation, un père décide seul d’inscrire son fils dans un autre collège, éloigné du domicile de la mère. La mère s’y oppose. L’inscription est-elle valable ?\nMajeure : l’autorité parentale est exercée en commun et le choix de l’établissement scolaire est un acte important, qui requiert l’accord des deux parents ; à défaut, le juge aux affaires familiales tranche.\nMineure : le père a agi seul, sans l’accord de la mère, pour un changement d’établissement.\nConclusion : l’inscription n’est pas régulière ; la mère peut saisir le juge aux affaires familiales pour la faire écarter.', 1)
ON CONFLICT DO NOTHING;

-- 3. Quiz ------------------------------------------------------------------
-- Double garde : ON CONFLICT (id) protège du rejeu, et le NOT EXISTS protège
-- la leçon d’un SECOND quiz venu d’ailleurs — le hub de leçon lit son quiz en
-- .maybeSingle(), deux quiz feraient lever « multiple rows » à de vrais élèves.
INSERT INTO public.quizzes (id, title, subject, grade_level, chapter, is_free, lesson_id)
SELECT v.id, v.title, v.subject, v.grade_level, v.chapter, true, l.id
  FROM (VALUES
    ('6851971d-80a3-5dc8-9799-e47b7f8ee09e'::uuid, 'Quiz — Qu’est-ce qu’une règle de droit ?', 'Droit civil', 'L1 droit', 'Introduction au droit : la règle de droit', 'd42f5e39-1af4-58af-a9b2-b19bce2c2191'::uuid),
    ('8b112644-ead3-5665-b3da-77bb50d54d42'::uuid, 'Quiz — D’où vient la règle de droit, et laquelle l’emporte ?', 'Droit civil', 'L1 droit', 'Les sources du droit et la hiérarchie des normes', '5190b799-01de-58bc-af08-f06aedeb7a5b'::uuid),
    ('64e3fd3c-3168-5d7b-befd-c33fb67ac263'::uuid, 'Quiz — Prouver un droit : charge, objet et modes de preuve', 'Droit civil', 'L1 droit', 'La preuve des droits', 'e6459575-96a5-56da-b842-a3270510800a'::uuid),
    ('4a4885a8-ff0b-5e7d-a080-d15d63f49334'::uuid, 'Quiz — Être une personne en droit : naissance, fin et droits de la personnalité', 'Droit civil', 'L1 droit', 'Les personnes physiques : la personnalité juridique', '041fcc9c-ce1d-5aa8-973f-3d4848518c28'::uuid),
    ('9c553c68-dda2-53d3-b425-e8730bbd8656'::uuid, 'Quiz — Identifier une personne : nom, prénoms, domicile, sexe et actes', 'Droit civil', 'L1 droit', 'L’état civil : nom, domicile, actes', '99a18fe9-3711-5b44-9b1b-50efc3923b1f'::uuid),
    ('5bb0df8a-59a6-5c16-9a68-e9f8ef9b721e'::uuid, 'Quiz — Protéger ceux qui ne peuvent agir seuls : mineurs et majeurs protégés', 'Droit civil', 'L1 droit', 'Les incapacités : mineurs et majeurs protégés', 'bcb867f7-c9c9-5ff0-a6d9-b2390e21e1c6'::uuid),
    ('5c049de5-81ba-50d4-afb3-96aec90a5c7c'::uuid, 'Quiz — Les groupements dotés de la personnalité juridique', 'Droit civil', 'L1 droit', 'Les personnes morales', '154cd255-343a-5aea-ac07-bc84ebb2549c'::uuid),
    ('61d0f3fe-1d19-5f27-b687-8fbc2fe5147e'::uuid, 'Quiz — Trois façons de vivre en couple : mariage, PACS et concubinage', 'Droit civil', 'L1 droit', 'Le couple : mariage, PACS, concubinage', '439814fc-bc7c-5fc7-8376-fb9b80c36349'::uuid),
    ('8dd6b9f5-9441-5d51-8252-293433012d0f'::uuid, 'Quiz — Les quatre cas de divorce et leurs effets', 'Droit civil', 'L1 droit', 'Le divorce', '242b4966-2598-5f2f-bc89-164d46003032'::uuid),
    ('76d63bfb-efd0-54bc-93e1-db29f11f15c8'::uuid, 'Quiz — Établir, contester et faire reconnaître un lien de filiation', 'Droit civil', 'L1 droit', 'La filiation', '1956ab56-ff54-51f1-8dfb-411f6130a387'::uuid),
    ('f2852c41-826b-51c1-818c-4994241c5e90'::uuid, 'Quiz — Les droits et devoirs des parents envers leur enfant', 'Droit civil', 'L1 droit', 'L’autorité parentale', '0c944ac0-b80c-5b04-a762-a986ac22b2b3'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('f3a17129-a3ed-5bc1-b82c-edb48dab6886'::uuid, '6851971d-80a3-5dc8-9799-e47b7f8ee09e'::uuid, 'Quel caractère distingue la règle de droit de la règle morale ?', 'mcq', '["Sa généralité","Son caractère abstrait","Sa sanction par la contrainte étatique","Son origine ancienne"]'::jsonb, 2, 'Seule la règle de droit est assortie d’une sanction que l’État peut imposer par la contrainte.', 1),
    ('e2155e41-0cd2-5953-9cfa-67b7bccceeb1'::uuid, '6851971d-80a3-5dc8-9799-e47b7f8ee09e'::uuid, 'Le droit subjectif est…', 'mcq', '["Une prérogative reconnue à une personne par le droit objectif","Le droit appliqué par un juge subjectif","Une règle morale","L’ensemble des lois en vigueur"]'::jsonb, 0, 'Le droit objectif est la règle ; le droit subjectif est la prérogative que cette règle confère (propriété, créance).', 2),
    ('566e3c5d-b1f8-5f03-8940-7a6da937044d'::uuid, '6851971d-80a3-5dc8-9799-e47b7f8ee09e'::uuid, 'Une règle supplétive s’applique même si les parties ont prévu autre chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une règle supplétive ne s’applique qu’à défaut de volonté contraire des parties ; c’est la règle impérative qui s’impose.', 3),
    ('a3763fb0-c737-548d-92c4-2ed333bb85e6'::uuid, '6851971d-80a3-5dc8-9799-e47b7f8ee09e'::uuid, 'Quel article du Code civil interdit de déroger par convention aux lois d’ordre public ?', 'mcq', '["L’article 1240","L’article 1er","L’article 2","L’article 6"]'::jsonb, 3, 'L’article 6 interdit de déroger par des conventions particulières aux lois qui intéressent l’ordre public et les bonnes mœurs.', 4),
    ('dcc01523-8e14-590b-9908-08dee7b50175'::uuid, '6851971d-80a3-5dc8-9799-e47b7f8ee09e'::uuid, 'Le juge peut refuser de trancher un litige quand la loi est silencieuse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’article 4 du Code civil l’interdit : le juge qui refuse de juger commet un déni de justice.', 5),
    ('ada8aded-3652-516a-8d24-4d3584a080c9'::uuid, '6851971d-80a3-5dc8-9799-e47b7f8ee09e'::uuid, 'Selon l’article 2 du Code civil, la loi…', 'mcq', '["S’applique toujours aux situations passées","Ne s’applique qu’aux contrats","Peut être écartée par le juge","Dispose pour l’avenir et n’a pas d’effet rétroactif"]'::jsonb, 3, 'La non-rétroactivité est le principe : la loi nouvelle ne remet pas en cause les situations juridiques déjà constituées.', 6),
    ('bb4b5389-0537-5dab-9ac5-90bc5f4e2b03'::uuid, '6851971d-80a3-5dc8-9799-e47b7f8ee09e'::uuid, 'Laquelle de ces branches relève du droit privé ?', 'mcq', '["Le droit des finances publiques","Le droit civil","Le droit administratif","Le droit constitutionnel"]'::jsonb, 1, 'Le droit civil règle les rapports entre particuliers : c’est le droit commun du droit privé.', 7),
    ('060c9451-7016-58ee-99a7-c51880269715'::uuid, '6851971d-80a3-5dc8-9799-e47b7f8ee09e'::uuid, 'Que signifie le caractère « abstrait » de la règle de droit ?', 'mcq', '["Elle n’est jamais sanctionnée","Elle est difficile à comprendre","Elle prévoit une situation type et non un cas particulier","Elle n’est pas écrite"]'::jsonb, 2, 'La règle est conçue pour une hypothèse-type, applicable à toutes les situations qui y correspondent.', 8),
    ('cf986ebb-6b4d-5562-bd79-2ec6f2527452'::uuid, '6851971d-80a3-5dc8-9799-e47b7f8ee09e'::uuid, 'Le droit de propriété est un droit…', 'mcq', '["Extrapatrimonial","Patrimonial","Public","Sans valeur économique"]'::jsonb, 1, 'Évaluable en argent, la propriété est un droit réel patrimonial.', 9),
    ('a919dd46-43c3-582e-817e-4d356a5c18c0'::uuid, '6851971d-80a3-5dc8-9799-e47b7f8ee09e'::uuid, 'Que fait l’article 5 du Code civil ?', 'mcq', '["Il interdit au juge de statuer par voie de disposition générale et réglementaire","Il fixe la majorité","Il définit le contrat","Il oblige le juge à juger"]'::jsonb, 0, 'Le juge tranche un cas d’espèce ; il ne peut édicter de règle générale à la façon d’un législateur (arrêt de règlement interdit).', 10),
    ('c9f2475a-edab-5fe1-9533-d7babdca86ee'::uuid, '6851971d-80a3-5dc8-9799-e47b7f8ee09e'::uuid, 'Le droit au respect de la vie privée est un droit…', 'mcq', '["Extrapatrimonial","Public","Réel","De créance"]'::jsonb, 0, 'Attaché à la personne et non évaluable en argent, il est extrapatrimonial et hors commerce.', 11),
    ('269a96a9-921f-5f29-ba15-5cc6ddadc012'::uuid, '6851971d-80a3-5dc8-9799-e47b7f8ee09e'::uuid, 'Pourquoi dit-on que le droit civil est le « droit commun » du droit privé ?', 'mcq', '["Parce qu’il s’applique seulement aux citoyens ordinaires","Parce qu’il est le plus ancien de tous les droits","Parce qu’il fournit les règles générales applicables à défaut de règle spéciale","Parce qu’il est connu de tous"]'::jsonb, 2, 'Les branches spéciales (commercial, travail) dérogent au droit civil ; à défaut de dérogation, c’est lui qui s’applique.', 12),
    ('13ea396e-420e-556d-bf7b-fba8b92f7cc1'::uuid, '8b112644-ead3-5665-b3da-77bb50d54d42'::uuid, 'Quelle est la norme la plus élevée de l’ordre juridique interne ?', 'mcq', '["La Constitution","La loi","Le règlement","Le traité"]'::jsonb, 0, 'La Constitution (et le bloc de constitutionnalité) est au sommet de la hiérarchie des normes internes.', 1),
    ('f369958f-3680-564a-a7ae-1584892f0958'::uuid, '8b112644-ead3-5665-b3da-77bb50d54d42'::uuid, 'Quel texte ne fait PAS partie du bloc de constitutionnalité ?', 'mcq', '["La Déclaration de 1789","Le Préambule de 1946","Le Code civil de 1804","La Charte de l’environnement de 2004"]'::jsonb, 2, 'Le Code civil est une loi ordinaire ; il n’a pas valeur constitutionnelle.', 2),
    ('b4770fb9-731c-564d-b327-7e534fee4faf'::uuid, '8b112644-ead3-5665-b3da-77bb50d54d42'::uuid, 'Une directive européenne est directement applicable sans transposition.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le règlement qui est directement applicable ; la directive doit être transposée par les États.', 3),
    ('e791e728-db44-5229-90d3-1bda42a17261'::uuid, '8b112644-ead3-5665-b3da-77bb50d54d42'::uuid, 'L’article 55 de la Constitution donne aux traités une autorité…', 'mcq', '["Supérieure à celle des lois, sous réserve de réciprocité","Nulle sans vote du Parlement","Inférieure à la loi","Égale à celle de la Constitution"]'::jsonb, 0, 'Les traités ratifiés ont une autorité supérieure à celle des lois, sous condition de réciprocité.', 4),
    ('049b61aa-6be9-5bc2-a1db-bc0102d05952'::uuid, '8b112644-ead3-5665-b3da-77bb50d54d42'::uuid, 'Qu’est-ce que le contrôle de conventionnalité ?', 'mcq', '["Le contrôle de la coutume","Le contrôle de la loi par rapport à la Constitution","Le contrôle de la loi par rapport aux traités","Le contrôle d’un contrat par le notaire"]'::jsonb, 2, 'Le juge écarte la loi contraire à un traité (arrêts Jacques Vabre, 1975, et Nicolo, 1989).', 5),
    ('7e759a70-e1b8-5c67-b422-38ff4731cd4a'::uuid, '8b112644-ead3-5665-b3da-77bb50d54d42'::uuid, 'Quel article de la Constitution fixe le domaine de la loi ?', 'mcq', '["L’article 34","L’article 37","L’article 55","L’article 61-1"]'::jsonb, 0, 'L’article 34 énumère les matières réservées à la loi ; le reste est réglementaire (article 37).', 6),
    ('03fa50c8-e145-5130-b361-47d54febbf9c'::uuid, '8b112644-ead3-5665-b3da-77bb50d54d42'::uuid, 'Un décret contraire à la loi est…', 'mcq', '["Illégal et annulable par le juge administratif","Inconstitutionnel et annulé par le Conseil constitutionnel","Une source de jurisprudence","Valable car plus récent"]'::jsonb, 0, 'Le règlement est inférieur à la loi ; sa contrariété à la loi se sanctionne par un recours pour excès de pouvoir.', 7),
    ('aaea6415-1c70-5f89-9926-e55753d97a48'::uuid, '8b112644-ead3-5665-b3da-77bb50d54d42'::uuid, 'La jurisprudence est formellement une source obligatoire du droit civil.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’article 5 interdit les arrêts de règlement ; la jurisprudence n’a pas de force obligatoire formelle, même si elle est très influente.', 8),
    ('8df0f3e8-e7f9-5a9f-8a69-135c60eb67ea'::uuid, '8b112644-ead3-5665-b3da-77bb50d54d42'::uuid, 'Que permet la QPC (article 61-1 de la Constitution) ?', 'mcq', '["De modifier la Constitution","De contester un décret devant le juge pénal","De faire contrôler, après promulgation, la conformité d’une loi aux droits garantis par la Constitution","De saisir directement la Cour de justice de l’Union"]'::jsonb, 2, 'Sur renvoi d’une juridiction, le Conseil constitutionnel peut abroger une loi portant atteinte aux droits et libertés constitutionnels.', 9),
    ('f416574d-ccfb-5de0-a38c-8652c5036f42'::uuid, '8b112644-ead3-5665-b3da-77bb50d54d42'::uuid, 'Quelle est la place du règlement dans la hiérarchie ?', 'mcq', '["Au-dessus de la loi","Au même niveau que la Constitution","En dessous de la loi","Hors hiérarchie"]'::jsonb, 2, 'Le règlement est inférieur à la loi (et aux normes supérieures).', 10),
    ('b988e1f3-3ebf-5482-a9da-bd1ff1daa137'::uuid, '8b112644-ead3-5665-b3da-77bb50d54d42'::uuid, 'Une pratique ancienne ressentie comme obligatoire est…', 'mcq', '["Une coutume","Une directive","Une circulaire","Une ordonnance"]'::jsonb, 0, 'La coutume suppose un usage répété et la conviction qu’il est obligatoire ; elle subsiste surtout en droit commercial.', 11),
    ('69358612-219a-5266-aadb-5b9ef6c4fcc7'::uuid, '8b112644-ead3-5665-b3da-77bb50d54d42'::uuid, 'Les ordonnances de l’article 38 sont prises par…', 'mcq', '["Le Gouvernement, sur habilitation du Parlement","La Cour de cassation","Le Parlement","Le Conseil constitutionnel"]'::jsonb, 0, 'Le Gouvernement peut légiférer dans le domaine de la loi, pour une durée limitée, après autorisation du Parlement.', 12),
    ('7ae10813-8525-5a2b-bf97-754708c160f7'::uuid, '64e3fd3c-3168-5d7b-befd-c33fb67ac263'::uuid, 'Qui supporte en principe la charge de la preuve ?', 'mcq', '["Le juge","Le ministère public","Toujours le défendeur","Celui qui réclame l’exécution d’une obligation"]'::jsonb, 3, 'L’article 1353 : celui qui réclame l’exécution d’une obligation doit la prouver.', 1),
    ('c285ee0a-044b-547d-8c1d-b1fb5ac11875'::uuid, '64e3fd3c-3168-5d7b-befd-c33fb67ac263'::uuid, 'Un accident de la circulation est…', 'mcq', '["Un aveu","Un acte juridique","Un fait juridique, prouvable par tous moyens","Un acte authentique"]'::jsonb, 2, 'C’est un événement : la preuve en est libre (témoins, photos, constat).', 2),
    ('b97e1d16-ca23-55f6-87a7-4b87e9d0c5b6'::uuid, '64e3fd3c-3168-5d7b-befd-c33fb67ac263'::uuid, 'Au-delà de quel seuil un acte juridique doit-il être prouvé par écrit ?', 'mcq', '["150 euros","500 euros","1 500 euros","15 000 euros"]'::jsonb, 2, 'Le seuil, fixé par décret, est de 1 500 euros (article 1359).', 3),
    ('9264ffdf-6aec-5cf9-9e38-9dee6c197e24'::uuid, '64e3fd3c-3168-5d7b-befd-c33fb67ac263'::uuid, 'Nul ne peut se constituer de preuve à soi-même.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Article 1363 : un écrit établi par une seule partie, à son profit, ne prouve pas contre l’autre.', 4),
    ('78a8525a-1b83-5098-9cda-fd3ccb74dc94'::uuid, '64e3fd3c-3168-5d7b-befd-c33fb67ac263'::uuid, 'L’acte authentique fait foi…', 'mcq', '["Pendant un an","Seulement entre les parties","Jusqu’à preuve contraire par témoins","Jusqu’à inscription de faux"]'::jsonb, 3, 'L’acte authentique, établi par un officier public, ne peut être contesté que par la procédure d’inscription de faux.', 5),
    ('904f4e74-ac81-5066-b9c3-a6d3432ebf52'::uuid, '64e3fd3c-3168-5d7b-befd-c33fb67ac263'::uuid, 'Une présomption irréfragable…', 'mcq', '["N’existe qu’en droit pénal","Admet la preuve contraire","N’admet aucune preuve contraire","Doit être écrite"]'::jsonb, 2, 'Elle est péremptoire : la preuve contraire est exclue, à la différence de la présomption simple.', 6),
    ('81beeb02-7486-53a7-af07-1de5e18d7a25'::uuid, '64e3fd3c-3168-5d7b-befd-c33fb67ac263'::uuid, 'Quel texte réforme le droit de la preuve en 2016 ?', 'mcq', '["La loi du 4 mars 2002","L’ordonnance du 10 février 2016","La loi du 23 mars 2019","La loi du 2 août 2021"]'::jsonb, 1, 'L’ordonnance du 10 février 2016 a réécrit les articles 1353 et suivants du Code civil.', 7),
    ('04b11a09-2210-588a-8aa7-0d86af29f884'::uuid, '64e3fd3c-3168-5d7b-befd-c33fb67ac263'::uuid, 'Un message électronique peut avoir la même force probante qu’un écrit papier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Si son auteur est identifiable et son intégrité garantie (article 1366).', 8),
    ('309ad4e6-9ee6-55f0-93da-44ca7a43cea4'::uuid, '64e3fd3c-3168-5d7b-befd-c33fb67ac263'::uuid, 'Qu’est-ce qu’un commencement de preuve par écrit ?', 'mcq', '["Un témoignage écrit","Un reçu de paiement","Un écrit émanant de celui à qui on l’oppose et rendant vraisemblable le fait allégué","Une preuve établie par l’huissier"]'::jsonb, 2, 'Il rend vraisemblable le fait et autorise à le compléter par témoins ou présomptions (article 1362).', 9),
    ('4d135174-070a-57a5-bb50-c4ddc733ba53'::uuid, '64e3fd3c-3168-5d7b-befd-c33fb67ac263'::uuid, 'Un contrat de vente de 5 000 euros entre deux particuliers peut en principe être prouvé uniquement par témoins.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Au-delà de 1 500 euros, l’écrit est exigé, sauf impossibilité ou commencement de preuve par écrit.', 10),
    ('717888f7-6183-516e-a673-b301506b7f6f'::uuid, '64e3fd3c-3168-5d7b-befd-c33fb67ac263'::uuid, 'L’article 9 du Code de procédure civile dispose que…', 'mcq', '["Chaque partie doit prouver les faits nécessaires au succès de sa prétention","Le juge doit rechercher seul la vérité","Toute preuve illégale est admise","Seul l’écrit est recevable"]'::jsonb, 0, 'Il incombe à chaque partie de prouver conformément à la loi les faits nécessaires au succès de sa prétention.', 11),
    ('fcf3e6ba-e73b-5b5b-ae1c-39ec3ee05bed'::uuid, '64e3fd3c-3168-5d7b-befd-c33fb67ac263'::uuid, 'Que désigne l’aveu en matière civile ?', 'mcq', '["La déclaration par laquelle une partie reconnaît pour vrai un fait qui peut lui nuire","Un témoignage anonyme","Un acte sous signature privée","La déclaration du juge"]'::jsonb, 0, 'L’aveu est la reconnaissance, par une partie, d’un fait de nature à produire contre elle des conséquences juridiques.', 12),
    ('b0e7775f-8b43-5909-897f-a4b930828e5c'::uuid, '4a4885a8-ff0b-5e7d-a080-d15d63f49334'::uuid, 'À quel moment commence en principe la personnalité juridique ?', 'mcq', '["À la naissance, si l’enfant naît vivant et viable","À la majorité","À l’inscription sur le livret de famille","À la conception"]'::jsonb, 0, 'Le principe est la naissance vivant et viable ; l’enfant conçu est seulement considéré comme né quand son intérêt l’exige.', 1),
    ('4028630e-5210-5ffa-90b7-c6a362a96140'::uuid, '4a4885a8-ff0b-5e7d-a080-d15d63f49334'::uuid, 'Que permet l’article 906 du Code civil ?', 'mcq', '["De vendre ses organes","De changer de nom","De déshériter un enfant","À une personne conçue de recevoir une donation ou un legs, sous réserve de naître viable"]'::jsonb, 3, 'Il applique l’adage infans conceptus : il suffit d’être conçu, à condition de naître viable.', 2),
    ('6f3b7bcd-5264-5cf4-8111-445e97da7ce1'::uuid, '4a4885a8-ff0b-5e7d-a080-d15d63f49334'::uuid, 'La personnalité juridique peut être retirée à un condamné.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La mort civile a disparu : tout être humain a la personnalité juridique et la capacité de jouissance.', 3),
    ('299ffc1d-1805-5faa-8ee9-34263e9b7ea6'::uuid, '4a4885a8-ff0b-5e7d-a080-d15d63f49334'::uuid, 'La capacité d’exercice est…', 'mcq', '["L’aptitude à être titulaire de droits","L’aptitude à exercer soi-même ses droits","L’aptitude à voter","Le droit de travailler"]'::jsonb, 1, 'Elle peut être limitée pour protéger certaines personnes (mineurs, majeurs protégés), contrairement à la capacité de jouissance.', 4),
    ('01a635be-a1cb-5b53-ad2e-dd2fc00000b6'::uuid, '4a4885a8-ff0b-5e7d-a080-d15d63f49334'::uuid, 'Que dit l’article 16-1 du Code civil ?', 'mcq', '["Le corps appartient à la famille","Le corps peut être vendu en cas de nécessité","Le corps relève de la compétence du maire","Le corps humain est inviolable et ne peut faire l’objet d’un droit patrimonial"]'::jsonb, 3, 'Principes d’inviolabilité, d’indisponibilité et de non-patrimonialité du corps humain.', 5),
    ('b017224e-f256-5b6e-bc37-c36fd2d3943a'::uuid, '4a4885a8-ff0b-5e7d-a080-d15d63f49334'::uuid, 'Une convention de gestation pour le compte d’autrui est…', 'mcq', '["Nulle","Valable avec l’accord des deux familles","Valable si elle est gratuite","Valable si un notaire l’a reçue"]'::jsonb, 0, 'L’article 16-7 prononce la nullité de toute convention de procréation ou de gestation pour le compte d’autrui.', 6),
    ('e8bd57a0-b374-5e03-b31f-bbf122836968'::uuid, '4a4885a8-ff0b-5e7d-a080-d15d63f49334'::uuid, 'Les droits de la personnalité sont…', 'mcq', '["Réservés aux majeurs","Patrimoniaux et cessibles","Extrapatrimoniaux","Réels"]'::jsonb, 2, 'Attachés à la personne, ils ne s’achètent ni ne se vendent.', 7),
    ('128f7f29-d606-5fb8-97f0-82c75e996464'::uuid, '4a4885a8-ff0b-5e7d-a080-d15d63f49334'::uuid, 'Que sont des « commorientes » ?', 'mcq', '["Des personnes mortes dans le même événement sans qu’on sache qui est mort le premier","Des héritiers réservataires","Des tuteurs","Des époux séparés de biens"]'::jsonb, 0, 'Aucune ne succède à l’autre lorsqu’on ignore l’ordre des décès.', 8),
    ('3a9d5ff1-69e8-5365-94e2-492290924ac2'::uuid, '4a4885a8-ff0b-5e7d-a080-d15d63f49334'::uuid, 'Le droit au respect de la vie privée est consacré par…', 'mcq', '["L’article 1er","L’article 1103","L’article 544","L’article 9 du Code civil"]'::jsonb, 3, 'L’article 9 : chacun a droit au respect de sa vie privée.', 9),
    ('1e0dc02e-3f08-51bc-bb11-7cf6beadcf0f'::uuid, '4a4885a8-ff0b-5e7d-a080-d15d63f49334'::uuid, 'Un embryon est une personne juridique titulaire de tous les droits.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il bénéficie du respect de l’être humain dès le commencement de sa vie, mais n’est pas une personne juridique.', 10),
    ('24a40ba9-dfbc-56b9-bf5d-76191c0b7960'::uuid, '4a4885a8-ff0b-5e7d-a080-d15d63f49334'::uuid, 'Le consentement est exigé avant toute atteinte à l’intégrité du corps, sauf…', 'mcq', '["Jamais, il n’y a pas d’exception","Si un parent y consent pour un majeur","En cas de nécessité médicale pour la personne, lorsqu’elle ne peut consentir","Si le médecin le décide seul"]'::jsonb, 2, 'L’article 16-3 admet l’atteinte en cas de nécessité médicale pour la personne, lorsque son consentement ne peut être recueilli.', 11),
    ('61d6ac15-c038-5b0c-8358-440add3b1712'::uuid, '4a4885a8-ff0b-5e7d-a080-d15d63f49334'::uuid, 'L’absence d’une personne (art. 112 s.) vise…', 'mcq', '["Une personne dont on n’a plus de nouvelles et dont l’existence est incertaine","Un salarié non présent à son poste","Un témoin qui ne comparaît pas","Une personne en détention"]'::jsonb, 0, 'La personne a cessé de paraître au lieu de son domicile sans nouvelles ; la loi organise la protection de ses intérêts puis la déclaration d’absence ou de décès.', 12),
    ('de2f59c9-1593-50e0-a8ea-0494372cc2e2'::uuid, '9c553c68-dda2-53d3-b425-e8730bbd8656'::uuid, 'Que signifie que l’état des personnes est indisponible ?', 'mcq', '["On ne peut ni le vendre ni y renoncer","Il n’est pas accessible au public","Il est réservé aux majeurs","Il est toujours modifiable"]'::jsonb, 0, 'L’indisponibilité interdit de céder son état ou d’y renoncer par contrat.', 1),
    ('69ff7de9-5283-5101-bdbe-12434c9f6fc0'::uuid, '9c553c68-dda2-53d3-b425-e8730bbd8656'::uuid, 'Quel texte a permis en 2022 à toute personne majeure d’ajouter ou de substituer à son nom celui de son autre parent, une fois dans sa vie ?', 'mcq', '["La loi du 4 mars 2002","La loi du 17 mai 2013","La loi du 23 mars 2019","La loi du 2 mars 2022"]'::jsonb, 3, 'La loi du 2 mars 2022 relative au choix du nom issu de la filiation, en vigueur depuis le 1er juillet 2022.', 2),
    ('8a8727b0-6112-5323-a484-fa4e4f385cea'::uuid, '9c553c68-dda2-53d3-b425-e8730bbd8656'::uuid, 'Le nom d’usage figure sur l’acte de naissance et remplace le nom de famille.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le nom d’usage est un nom de la vie sociale ; il ne modifie pas le nom officiel porté dans les actes d’état civil.', 3),
    ('36faedbb-c888-5299-a695-862354b308bc'::uuid, '9c553c68-dda2-53d3-b425-e8730bbd8656'::uuid, 'Le domicile est, selon l’article 102 du Code civil…', 'mcq', '["Le lieu de travail","Le lieu où l’on est né","Le lieu du principal établissement","Toute résidence secondaire"]'::jsonb, 2, 'Le domicile est le lieu où la personne a son principal établissement ; la résidence est le lieu de séjour de fait.', 4),
    ('9b44005d-bb3f-5c39-9d2a-b1a009c98c3a'::uuid, '9c553c68-dda2-53d3-b425-e8730bbd8656'::uuid, 'Le mineur non émancipé a pour domicile légal…', 'mcq', '["Celui de son école","Celui de ses parents","Celui de son choix","Celui de son juge des enfants"]'::jsonb, 1, 'Le mineur non émancipé est domicilié chez ses parents.', 5),
    ('17ad890b-3ba9-5739-9209-1496bec94aab'::uuid, '9c553c68-dda2-53d3-b425-e8730bbd8656'::uuid, 'Quelle est la différence entre domicile et résidence ?', 'mcq', '["Le domicile est le principal établissement, la résidence est le lieu où l’on vit de fait","La résidence est toujours à l’étranger","Le domicile ne concerne que les entreprises","Aucune"]'::jsonb, 0, 'La résidence est une situation de fait ; le domicile, une notion juridique.', 6),
    ('2afce7a5-9cee-5f5a-a1fb-45b3e1e4946f'::uuid, '9c553c68-dda2-53d3-b425-e8730bbd8656'::uuid, 'Les actes d’état civil sont des actes…', 'mcq', '["De la jurisprudence","Sans force probante","Sous signature privée","Authentiques"]'::jsonb, 3, 'Ils sont établis par un officier public et font foi jusqu’à inscription de faux.', 7),
    ('afae070f-0ee4-5659-8687-e6e730dbe7e0'::uuid, '9c553c68-dda2-53d3-b425-e8730bbd8656'::uuid, 'Depuis la loi du 18 novembre 2016, le changement de la mention du sexe à l’état civil exige une opération chirurgicale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La loi ne l’exige pas : la personne doit démontrer que la mention ne correspond pas à son apparence et à son comportement social.', 8),
    ('4f1b1b6c-582a-566b-9f2e-5914a2ecc10f'::uuid, '9c553c68-dda2-53d3-b425-e8730bbd8656'::uuid, 'Que sont les mentions marginales ?', 'mcq', '["Les erreurs de l’officier d’état civil","Les mises à jour portées en marge d’un acte (mariage, divorce, reconnaissance)","Des sanctions pénales","Les noms d’usage"]'::jsonb, 1, 'Elles mettent à jour l’acte d’état civil sans en créer un nouveau.', 9),
    ('06f24f41-8de8-5442-ab8c-00d7dc0859c7'::uuid, '9c553c68-dda2-53d3-b425-e8730bbd8656'::uuid, 'Le changement de prénom se fait aujourd’hui…', 'mcq', '["Par décret","Par déclaration à l’officier de l’état civil, sur justification d’un intérêt légitime","Librement par simple lettre à l’employeur","Uniquement devant le Conseil d’État"]'::jsonb, 1, 'La loi du 18 novembre 2016 a déjudiciarisé la procédure : la demande se fait en mairie.', 10),
    ('3bdfb366-78ef-560d-9bdd-a8b4fc7f2601'::uuid, '9c553c68-dda2-53d3-b425-e8730bbd8656'::uuid, 'Un domicile élu est…', 'mcq', '["Le lieu de naissance","Un domicile fiscal","Le domicile légal d’un majeur protégé","Un domicile choisi pour l’exécution d’un acte"]'::jsonb, 3, 'Par exemple, on élit domicile chez son avocat ou chez le notaire pour les besoins d’un acte ou d’une instance.', 11),
    ('e46fc212-3b3b-5fed-95bd-02d2b517c838'::uuid, '9c553c68-dda2-53d3-b425-e8730bbd8656'::uuid, 'Selon le principe d’immutabilité du nom…', 'mcq', '["Le nom est choisi à 18 ans","Le nom ne peut jamais changer","On ne change pas de nom à sa guise : il faut un motif légitime ou une procédure prévue par la loi","Le nom change à la majorité"]'::jsonb, 2, 'Le nom est stable ; les exceptions sont limitativement prévues (motif légitime, loi de 2022, adoption, etc.).', 12),
    ('378c2837-c71e-59b7-a1dd-a210eb79e6c9'::uuid, '5bb0df8a-59a6-5c16-9a68-e9f8ef9b721e'::uuid, 'À quel âge est-on majeur en droit civil français ?', 'mcq', '["25 ans","16 ans","18 ans","21 ans"]'::jsonb, 2, 'L’article 414 fixe la majorité à 18 ans accomplis.', 1),
    ('f2f99bbb-230f-5ba5-8b70-d592b685d55c'::uuid, '5bb0df8a-59a6-5c16-9a68-e9f8ef9b721e'::uuid, 'Quel est l’âge minimum de l’émancipation ?', 'mcq', '["14 ans","15 ans","16 ans","17 ans"]'::jsonb, 2, 'Le mineur peut être émancipé dès 16 ans par le juge des tutelles (article 413-2).', 2),
    ('6dd259a4-89d3-5eac-abc8-767411ef81d1'::uuid, '5bb0df8a-59a6-5c16-9a68-e9f8ef9b721e'::uuid, 'Un mineur non émancipé peut valablement conclure un acte de la vie courante à des conditions normales.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Article 1148 : les actes courants autorisés par la loi ou l’usage sont valables même accomplis seuls.', 3),
    ('24bd2907-9b99-51ad-845f-65188480de65'::uuid, '5bb0df8a-59a6-5c16-9a68-e9f8ef9b721e'::uuid, 'Quelle mesure de protection fonctionne par REPRÉSENTATION ?', 'mcq', '["La sauvegarde de justice","Le mandat de protection future uniquement","La curatelle simple","La tutelle"]'::jsonb, 3, 'Dans la tutelle, le tuteur agit à la place de la personne protégée ; dans la curatelle, il l’assiste.', 4),
    ('a3b27bbf-9904-5659-bbab-f1da06a37ccc'::uuid, '5bb0df8a-59a6-5c16-9a68-e9f8ef9b721e'::uuid, 'Dans la curatelle, le curateur…', 'mcq', '["Décide à sa place du lieu de résidence","Représente la personne pour tous les actes","Assiste la personne pour les actes les plus graves","N’a aucun pouvoir"]'::jsonb, 2, 'La personne en curatelle agit seule pour les actes courants et est assistée pour les actes importants.', 5),
    ('ac3d761c-1c9d-54bf-9d56-95a667ed34dc'::uuid, '5bb0df8a-59a6-5c16-9a68-e9f8ef9b721e'::uuid, 'Quels sont les principes directeurs de toute mesure de protection ?', 'mcq', '["Rapidité, secret, gratuité","Nécessité, subsidiarité, proportionnalité","Autorité, discipline, sanction","Famille, patrimoine, état"]'::jsonb, 1, 'Article 428 : la mesure est ordonnée si elle est nécessaire, et seulement si une mesure moins contraignante ne suffit pas.', 6),
    ('779d89a8-0caf-5528-9c9e-0e844d7b4ecd'::uuid, '5bb0df8a-59a6-5c16-9a68-e9f8ef9b721e'::uuid, 'Qu’est-ce que le mandat de protection future ?', 'mcq', '["Une mesure anticipée par laquelle une personne désigne à l’avance qui s’occupera d’elle","Une tutelle pour les mineurs","Un contrat de travail","Une mesure décidée par le juge sans le consentement de l’intéressé"]'::jsonb, 0, 'Chacun peut organiser sa propre protection pour le cas où il ne pourrait plus pourvoir seul à ses intérêts.', 7),
    ('1a3e380c-6689-5230-8183-7ec992f345c6'::uuid, '5bb0df8a-59a6-5c16-9a68-e9f8ef9b721e'::uuid, 'La loi du 23 mars 2019 a permis…', 'mcq', '["D’abaisser la majorité à 16 ans","De supprimer la tutelle","De retirer le droit de vote à toute personne sous tutelle","De supprimer la privation du droit de vote des personnes sous tutelle"]'::jsonb, 3, 'Le juge ne peut plus priver du droit de vote les personnes sous tutelle.', 8),
    ('ce5dfced-ca63-52e2-acf1-61c6a9efca1a'::uuid, '5bb0df8a-59a6-5c16-9a68-e9f8ef9b721e'::uuid, 'Un mineur émancipé est capable comme un majeur, mais ne peut se marier avant 18 ans.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’émancipation donne la capacité civile, pas l’âge du mariage ; l’exercice du commerce suppose une autorisation du juge.', 9),
    ('ef4d50b0-8113-567c-a20c-5f59d83fd789'::uuid, '5bb0df8a-59a6-5c16-9a68-e9f8ef9b721e'::uuid, 'L’habilitation familiale permet…', 'mcq', '["À un proche d’être habilité à représenter un parent vulnérable, sans tutelle","De déshériter un incapable","D’émanciper un enfant","De dissoudre un mariage"]'::jsonb, 0, 'Issue de l’ordonnance du 15 octobre 2015, elle permet à un proche de représenter la personne sous contrôle limité du juge.', 10),
    ('10859449-15cc-572e-ace4-66e873121a74'::uuid, '5bb0df8a-59a6-5c16-9a68-e9f8ef9b721e'::uuid, 'Quelle sanction frappe en principe l’acte accompli seul par un mineur hors vie courante ?', 'mcq', '["La nullité relative","Une amende civile","Aucune, l’acte est valable","L’inexistence"]'::jsonb, 0, 'La nullité est relative : seul l’incapable protégé (ou son représentant) peut l’invoquer.', 11),
    ('42fa0538-1099-5298-a612-820cccdc3ab7'::uuid, '5bb0df8a-59a6-5c16-9a68-e9f8ef9b721e'::uuid, 'Quelle condition essentielle justifie l’ouverture d’une mesure de protection d’un majeur ?', 'mcq', '["Avoir des dettes","Une décision du maire","Une altération médicalement constatée des facultés, empêchant de pourvoir seul à ses intérêts","Avoir plus de 70 ans"]'::jsonb, 2, 'Article 425 : altération des facultés mentales ou corporelles de nature à empêcher l’expression de la volonté, constatée médicalement.', 12),
    ('7e0d9fcc-1b2d-5074-870c-3d373f8ceea6'::uuid, '5c049de5-81ba-50d4-afb3-96aec90a5c7c'::uuid, 'Qu’est-ce qu’une personne morale ?', 'mcq', '["Un mineur protégé","Un fonctionnaire","Une personne respectueuse de la morale","Un groupement doté de la personnalité juridique"]'::jsonb, 3, 'Elle est titulaire de droits et d’obligations, distincts de ceux de ses membres.', 1),
    ('19dd548c-9e27-580d-b184-a47ff0e698fb'::uuid, '5c049de5-81ba-50d4-afb3-96aec90a5c7c'::uuid, 'Laquelle de ces entités est une personne morale de droit public ?', 'mcq', '["Une SAS","Une SARL","Une association loi 1901","Une commune"]'::jsonb, 3, 'Les collectivités territoriales (communes, départements, régions) sont des personnes morales de droit public.', 2),
    ('6d99c7f9-fa3f-539b-b61a-2c0c9c662c00'::uuid, '5c049de5-81ba-50d4-afb3-96aec90a5c7c'::uuid, 'Une association a pour but de partager des bénéfices entre ses membres.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Au contraire : l’article 1er de la loi de 1901 exige un but autre que le partage de bénéfices.', 3),
    ('04d4c757-f6d0-5805-9650-a60df8b766be'::uuid, '5c049de5-81ba-50d4-afb3-96aec90a5c7c'::uuid, 'La société a la personnalité morale à compter…', 'mcq', '["De son immatriculation au RCS","De la première assemblée","De son premier bilan","De la signature des statuts"]'::jsonb, 0, 'L’article 1842 : les sociétés jouissent de la personnalité morale à compter de leur immatriculation.', 4),
    ('0b5beeec-e133-5262-b57a-d13c89cfaf0a'::uuid, '5c049de5-81ba-50d4-afb3-96aec90a5c7c'::uuid, 'L’article 1832 du Code civil définit…', 'mcq', '["La société","La propriété","L’association","Le contrat"]'::jsonb, 0, 'La société suppose des apports, un projet commun et le partage des bénéfices ou des économies.', 5),
    ('2c07293e-eaa6-5331-9bd1-d84a11ac7f9c'::uuid, '5c049de5-81ba-50d4-afb3-96aec90a5c7c'::uuid, 'Qu’est-ce que l’affectio societatis ?', 'mcq', '["La dissolution de la société","Le capital minimal","La volonté des associés de collaborer à égalité à l’entreprise commune","Le siège de la société"]'::jsonb, 2, 'C’est l’un des éléments constitutifs du contrat de société avec les apports et la participation aux résultats.', 6),
    ('7e8ae788-2c22-56e5-923b-6d6427fdc6e2'::uuid, '5c049de5-81ba-50d4-afb3-96aec90a5c7c'::uuid, 'Le principe de spécialité signifie que la personne morale…', 'mcq', '["Peut tout faire","Ne peut agir que dans les limites de son objet","Ne peut pas agir en justice","N’a pas de patrimoine"]'::jsonb, 1, 'Sa capacité est limitée à son objet défini par les statuts, sauf actes accessoires.', 7),
    ('b585008e-5c27-5c24-8cd0-21f1313640fa'::uuid, '5c049de5-81ba-50d4-afb3-96aec90a5c7c'::uuid, 'Les associés d’une SARL répondent des dettes de la société sur tous leurs biens personnels.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Leur responsabilité est limitée aux apports : le patrimoine de la société est distinct du leur.', 8),
    ('716a00a9-8c06-54ec-97ca-21c0dfdc80cd'::uuid, '5c049de5-81ba-50d4-afb3-96aec90a5c7c'::uuid, 'Un syndicat de salariés relève de la loi…', 'mcq', '["Du 17 mai 2013","Du 2 août 2021","Du 1er juillet 1901","Du 21 mars 1884"]'::jsonb, 3, 'La loi du 21 mars 1884 a reconnu la liberté syndicale.', 9),
    ('d2a3cfe3-a29f-5747-a005-a49a763fd6f0'::uuid, '5c049de5-81ba-50d4-afb3-96aec90a5c7c'::uuid, 'La personne morale exprime sa volonté par…', 'mcq', '["Ses créanciers","Ses clients","Ses organes (gérant, président, assemblée…)","Le juge"]'::jsonb, 2, 'Dépourvue de volonté propre, elle agit par l’intermédiaire de ses organes.', 10),
    ('221b1e43-06a7-5d76-8086-8ef0e8c6695b'::uuid, '5c049de5-81ba-50d4-afb3-96aec90a5c7c'::uuid, 'Quel est l’attribut de la personne morale équivalent du domicile ?', 'mcq', '["Le nom","Le siège social","La nationalité","L’objet social"]'::jsonb, 1, 'Le siège social est le lieu de son principal établissement.', 11),
    ('ee1b48e1-27b5-506c-9f0b-c0d6c76a919b'::uuid, '5c049de5-81ba-50d4-afb3-96aec90a5c7c'::uuid, 'La personne morale prend fin par…', 'mcq', '["La dissolution suivie de la liquidation","La majorité de ses associés","Le changement de nom","La mort de son dirigeant"]'::jsonb, 0, 'Après dissolution, la liquidation règle les dettes et répartit le solde.', 12),
    ('4f20f593-4a3b-58c4-878a-b91a6cc44d2d'::uuid, '61d0f3fe-1d19-5f27-b687-8fbc2fe5147e'::uuid, 'Quelle loi a ouvert le mariage aux couples de même sexe ?', 'mcq', '["La loi du 17 mai 2013","La loi du 4 mars 2002","La loi du 23 mars 2019","La loi du 15 novembre 1999"]'::jsonb, 0, 'La loi du 17 mai 2013 a ouvert le mariage aux personnes de même sexe (article 143 du Code civil).', 1),
    ('f395a63c-5d32-559b-a376-6c85d282078d'::uuid, '61d0f3fe-1d19-5f27-b687-8fbc2fe5147e'::uuid, 'Quel est l’âge minimal pour se marier ?', 'mcq', '["18 ans","21 ans","15 ans","16 ans"]'::jsonb, 0, 'L’article 144 impose dix-huit ans révolus.', 2),
    ('0b207059-0fce-5632-9a16-955317e05213'::uuid, '61d0f3fe-1d19-5f27-b687-8fbc2fe5147e'::uuid, 'Les époux se doivent fidélité, secours et assistance.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Article 212 : respect, fidélité, secours, assistance.', 3),
    ('054f96c5-4ddb-5142-b693-ee68140f56ee'::uuid, '61d0f3fe-1d19-5f27-b687-8fbc2fe5147e'::uuid, 'Quel est le régime matrimonial légal ?', 'mcq', '["La séparation de biens","La communauté universelle","La communauté réduite aux acquêts","La participation aux acquêts"]'::jsonb, 2, 'À défaut de contrat de mariage, les époux relèvent de la communauté réduite aux acquêts.', 4),
    ('824d6ed0-3b6c-52b0-bc08-1eb00ceffcb7'::uuid, '61d0f3fe-1d19-5f27-b687-8fbc2fe5147e'::uuid, 'Qu’organise l’article 220 du Code civil ?', 'mcq', '["La solidarité des époux pour les dettes ménagères","Le PACS","La filiation","Le divorce"]'::jsonb, 0, 'Un époux peut engager le ménage par les dettes d’entretien du ménage ou d’éducation des enfants.', 5),
    ('1e5d762d-8dfd-53a7-a55a-c3d58e38a9c0'::uuid, '61d0f3fe-1d19-5f27-b687-8fbc2fe5147e'::uuid, 'Un PACS peut être conclu par un mineur émancipé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les deux partenaires doivent être majeurs (article 515-1).', 6),
    ('22030a0d-e55d-52dc-bd55-e78c060d5227'::uuid, '61d0f3fe-1d19-5f27-b687-8fbc2fe5147e'::uuid, 'Le régime légal du PACS est…', 'mcq', '["La communauté universelle","La communauté","La séparation des patrimoines","La participation aux acquêts"]'::jsonb, 2, 'Chaque partenaire reste propriétaire de ses biens, sauf convention contraire (article 515-5).', 7),
    ('6b8c89db-9e18-5df4-aaca-329c41ce26ed'::uuid, '61d0f3fe-1d19-5f27-b687-8fbc2fe5147e'::uuid, 'Le concubinage est défini à…', 'mcq', '["L’article 143","L’article 515-1","L’article 515-8","L’article 220"]'::jsonb, 2, 'L’article 515-8 : une union de fait, avec vie commune stable et continue.', 8),
    ('9e47016c-fd14-5927-9634-26dc489c1326'::uuid, '61d0f3fe-1d19-5f27-b687-8fbc2fe5147e'::uuid, 'Le concubin survivant est héritier légal de son compagnon.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il n’hérite que s’il y a un testament ; ni le PACS ni le concubinage ne créent de vocation successorale légale.', 9),
    ('5126aab5-7672-54a3-94d1-98a36b11ed4f'::uuid, '61d0f3fe-1d19-5f27-b687-8fbc2fe5147e'::uuid, 'Comment se rompt un PACS ?', 'mcq', '["Il ne peut jamais se rompre","Par la volonté du maire","Par déclaration conjointe ou décision unilatérale signifiée","Par un divorce devant le juge"]'::jsonb, 2, 'Le PACS se dissout par déclaration conjointe, décision unilatérale, mariage ou décès.', 10),
    ('c9e11b6d-4da9-5759-beee-54b712c537f4'::uuid, '61d0f3fe-1d19-5f27-b687-8fbc2fe5147e'::uuid, 'Que protège l’article 215, alinéa 3, du Code civil ?', 'mcq', '["L’héritage","Le nom du conjoint","Le logement de la famille","La fidélité"]'::jsonb, 2, 'Aucun époux ne peut, seul, disposer des droits par lesquels est assuré le logement de la famille.', 11),
    ('cd55b1d1-fdaf-5f27-8ebe-85c0e03b7b2d'::uuid, '61d0f3fe-1d19-5f27-b687-8fbc2fe5147e'::uuid, 'Depuis la loi du 23 mars 2019, le changement de régime matrimonial…', 'mcq', '["Est interdit","Exige toujours deux ans et le juge","Peut se faire par acte notarié sans condition de délai","Se fait au tribunal"]'::jsonb, 2, 'Le délai de deux ans a été supprimé, et l’homologation judiciaire n’est plus obligatoire sauf opposition ou enfants mineurs.', 12),
    ('fad8b8f4-e710-5a54-9459-7ee8e8900c9c'::uuid, '8dd6b9f5-9441-5d51-8252-293433012d0f'::uuid, 'Combien de cas de divorce l’article 229 du Code civil énumère-t-il ?', 'mcq', '["Deux","Trois","Quatre","Cinq"]'::jsonb, 2, 'Consentement mutuel, acceptation du principe de la rupture, altération définitive du lien conjugal, faute.', 1),
    ('819003cf-54a3-5946-9dbf-4ff3c5b01044'::uuid, '8dd6b9f5-9441-5d51-8252-293433012d0f'::uuid, 'Depuis le 1er janvier 2017, le divorce par consentement mutuel peut être conclu…', 'mcq', '["Par acte sous signature privée contresigné par avocats, déposé chez un notaire","Seulement par le juge","Par simple lettre à l’autre époux","Devant le maire"]'::jsonb, 0, 'C’est la déjudiciarisation instituée par la loi du 18 novembre 2016 (article 229-1).', 2),
    ('8fd91069-24e5-5c21-9d2d-8553a5687130'::uuid, '8dd6b9f5-9441-5d51-8252-293433012d0f'::uuid, 'Dans le divorce par consentement mutuel par acte d’avocats, un juge intervient toujours.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il n’intervient pas, sauf si un enfant mineur demande à être entendu ou si un époux est sous régime de protection.', 3),
    ('6771f76d-6c89-590a-8d9e-8c6f790488bd'::uuid, '8dd6b9f5-9441-5d51-8252-293433012d0f'::uuid, 'La phase de conciliation préalable au divorce contentieux a été supprimée…', 'mcq', '["Elle existe toujours","En 2004","Le 1er janvier 2021","En 2013"]'::jsonb, 2, 'La loi du 23 mars 2019 a supprimé la tentative de conciliation et simplifié l’introduction de l’instance depuis le 1er janvier 2021.', 4),
    ('388e399b-1663-5d59-8ea5-6b5ccd3420aa'::uuid, '8dd6b9f5-9441-5d51-8252-293433012d0f'::uuid, 'Quel est le délai de séparation nécessaire pour établir l’altération définitive du lien conjugal ?', 'mcq', '["Six mois","Un an","Deux ans","Cinq ans"]'::jsonb, 1, 'Depuis la réforme de 2019, la cessation de la communauté de vie depuis un an (article 238).', 5),
    ('c99d0952-1769-562f-9dea-fa9e73d0edd1'::uuid, '8dd6b9f5-9441-5d51-8252-293433012d0f'::uuid, 'Dans quel cas le divorce pour faute est-il possible ?', 'mcq', '["En cas de violations graves ou renouvelées des devoirs du mariage rendant intolérable le maintien de la vie commune","Si les époux n’ont pas d’enfant","Seulement après dix ans de mariage","Dès qu’un époux est mécontent"]'::jsonb, 0, 'L’article 242 pose cette double exigence : gravité ou répétition, et caractère intolérable du maintien de la vie commune.', 6),
    ('3fa08cb1-047d-5f5a-9503-365ad2929cd2'::uuid, '8dd6b9f5-9441-5d51-8252-293433012d0f'::uuid, 'La prestation compensatoire a pour but de…', 'mcq', '["Financer l’avocat","Partager les dettes","Sanctionner l’époux fautif","Compenser la disparité des conditions de vie créée par la rupture"]'::jsonb, 3, 'Article 270 : elle compense la disparité que la rupture du mariage crée dans les conditions de vie respectives.', 7),
    ('928f4b5a-bfd7-5160-9e84-0f94f395ff12'::uuid, '8dd6b9f5-9441-5d51-8252-293433012d0f'::uuid, 'La prestation compensatoire prend en principe la forme…', 'mcq', '["D’un usufruit","D’une rente viagère","D’un capital","D’une pension mensuelle"]'::jsonb, 2, 'Le capital est la règle ; la rente viagère est exceptionnelle.', 8),
    ('c7d09c91-d023-591c-9389-3437f2bb38bc'::uuid, '8dd6b9f5-9441-5d51-8252-293433012d0f'::uuid, 'Le divorce met fin à l’autorité parentale conjointe sur les enfants.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle subsiste : la séparation des parents est sans incidence sur les règles de son exercice.', 9),
    ('8230d4e6-af26-54e3-af0e-84285a2dc393'::uuid, '8dd6b9f5-9441-5d51-8252-293433012d0f'::uuid, 'Quel juge est compétent pour le divorce contentieux ?', 'mcq', '["Le juge aux affaires familiales","Le juge des enfants","Le juge de l’exécution","Le juge d’instruction"]'::jsonb, 0, 'Le JAF, au sein du tribunal judiciaire, statue sur le divorce et ses conséquences.', 10),
    ('20a64a42-9005-5c89-a243-221ec0ecec0f'::uuid, '8dd6b9f5-9441-5d51-8252-293433012d0f'::uuid, 'La procédure contentieuse de divorce débute désormais par…', 'mcq', '["Une tentative de conciliation obligatoire","Une plainte pénale","Une requête devant le maire","Une assignation ou une requête conjointe"]'::jsonb, 3, 'Depuis 2021, plus de requête initiale ni de conciliation : l’instance s’ouvre par assignation, ou par requête conjointe.', 11),
    ('257e2b4d-f9cf-588e-8223-9f1c28bda118'::uuid, '8dd6b9f5-9441-5d51-8252-293433012d0f'::uuid, 'À quelle date le divorce prend-il effet, en principe, dans les rapports patrimoniaux entre époux ?', 'mcq', '["À la date de la liquidation","À la date de la demande en divorce","À la date de la célébration du mariage","À la date de la majorité des enfants"]'::jsonb, 1, 'Le jugement prend effet à la date de la demande, avec possibilité de report à la date de cessation de la cohabitation et de la collaboration.', 12),
    ('9f6fc1a2-f99e-55f3-bb41-b6cc6238d860'::uuid, '76d63bfb-efd0-54bc-93e1-db29f11f15c8'::uuid, 'Que prévoit l’article 310 du Code civil ?', 'mcq', '["Le droit au nom d’usage","L’égalité de tous les enfants dans leurs rapports avec leurs parents","La majorité à 18 ans","La présomption de paternité"]'::jsonb, 1, 'Tous les enfants dont la filiation est légalement établie ont les mêmes droits et devoirs.', 1),
    ('620333f9-ca67-55c8-95a4-77412023138d'::uuid, '76d63bfb-efd0-54bc-93e1-db29f11f15c8'::uuid, 'Comment s’établit la filiation maternelle de principe ?', 'mcq', '["Par une reconnaissance obligatoire","Par la désignation de la mère dans l’acte de naissance","Par une expertise biologique","Par décision du juge"]'::jsonb, 1, 'Article 311-25 : la filiation est établie à l’égard de la mère par sa désignation dans l’acte de naissance.', 2),
    ('ffa97f34-2069-5434-9957-2ce6bf6af1dc'::uuid, '76d63bfb-efd0-54bc-93e1-db29f11f15c8'::uuid, 'La présomption de paternité s’applique à l’enfant né pendant le mariage de sa mère.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Article 312 : l’enfant conçu ou né pendant le mariage a pour père le mari.', 3),
    ('1c134c9b-9a7f-59b5-809f-b105462bdc7f'::uuid, '76d63bfb-efd0-54bc-93e1-db29f11f15c8'::uuid, 'La reconnaissance d’un enfant peut être faite…', 'mcq', '["Uniquement par le juge","Seulement par la mère","Seulement après sa naissance","Avant ou après la naissance, devant un officier d’état civil ou un notaire"]'::jsonb, 3, 'La reconnaissance prénatale est possible.', 4),
    ('72241c1d-a176-5b2d-b6bf-38f5eea6d94f'::uuid, '76d63bfb-efd0-54bc-93e1-db29f11f15c8'::uuid, 'Qu’est-ce que la possession d’état ?', 'mcq', '["Un jugement","Un titre de propriété","Un faisceau de faits publics et continus révélant le lien de filiation","Un acte notarié"]'::jsonb, 2, 'Nom porté, traitement comme enfant, reconnaissance par l’entourage.', 5),
    ('74cf9df2-7f92-5122-9428-d2fa0e59170c'::uuid, '76d63bfb-efd0-54bc-93e1-db29f11f15c8'::uuid, 'Quelle loi a ouvert la PMA à toutes les femmes ?', 'mcq', '["La loi du 4 mars 2002","La loi du 17 mai 2013","La loi du 2 août 2021","La loi du 2 mars 2022"]'::jsonb, 2, 'La loi bioéthique du 2 août 2021 a ouvert l’AMP aux couples de femmes et aux femmes seules.', 6),
    ('b3e8dd6a-ba44-5f70-9b89-a4df8d3119e6'::uuid, '76d63bfb-efd0-54bc-93e1-db29f11f15c8'::uuid, 'Dans un couple de femmes ayant recours à une PMA, la filiation envers la femme qui n’accouche pas s’établit par…', 'mcq', '["La reconnaissance conjointe anticipée devant notaire","La présomption de paternité","Un test génétique","L’adoption forcée"]'::jsonb, 0, 'Article 342-11 : consentement et reconnaissance conjointe anticipée devant notaire avant la PMA.', 7),
    ('42b14cb4-9d00-5ff0-b23b-a93bfc716f25'::uuid, '76d63bfb-efd0-54bc-93e1-db29f11f15c8'::uuid, 'La gestation pour autrui est autorisée en France depuis la loi bioéthique de 2021.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle reste interdite : toute convention de gestation pour le compte d’autrui est nulle (article 16-7).', 8),
    ('bcfc5c30-51db-5027-b201-2ec5819c3fde'::uuid, '76d63bfb-efd0-54bc-93e1-db29f11f15c8'::uuid, 'L’adoption plénière…', 'mcq', '["Est réservée aux majeurs","S’ajoute à la filiation d’origine","Remplace la filiation d’origine et est irrévocable","N’existe pas en France"]'::jsonb, 2, 'Elle substitue une nouvelle filiation à celle d’origine, de façon irrévocable.', 9),
    ('50f8b097-d692-5993-8249-7c877805c9c0'::uuid, '76d63bfb-efd0-54bc-93e1-db29f11f15c8'::uuid, 'Quelle est la prescription de droit commun des actions relatives à la filiation (art. 321) ?', 'mcq', '["Un an","Cinq ans","Dix ans","Trente ans"]'::jsonb, 2, 'L’action se prescrit par dix ans à compter du jour où la personne a été privée de l’état qu’elle réclame ou a commencé à jouir de l’état qu’on lui conteste.', 10),
    ('6a0f9a71-89d0-521c-9c8e-f8dae8a937aa'::uuid, '76d63bfb-efd0-54bc-93e1-db29f11f15c8'::uuid, 'Dans l’adoption simple…', 'mcq', '["L’adopté conserve ses liens avec sa famille d’origine","L’adoption est interdite aux couples","L’adopté change forcément de nationalité","L’adopté perd tous ses liens avec sa famille d’origine"]'::jsonb, 0, 'Elle ajoute une filiation sans effacer l’existante.', 11),
    ('3f9363e4-7c26-5ff3-a04f-1766b90b6e55'::uuid, '76d63bfb-efd0-54bc-93e1-db29f11f15c8'::uuid, 'Qu’est-ce que l’accouchement « sous X » ?', 'mcq', '["Une adoption","Un accouchement à domicile","Un accouchement à l’étranger","Un accouchement où la mère demande que le secret de son identité soit préservé"]'::jsonb, 3, 'L’article 326 : lors de l’accouchement, la mère peut demander que le secret de son admission et de son identité soit préservé.', 12),
    ('5d336cf5-5e58-5de1-853e-a09d482ab08f'::uuid, 'f2852c41-826b-51c1-818c-4994241c5e90'::uuid, 'Quelle est la finalité de l’autorité parentale selon l’article 371-1 ?', 'mcq', '["La protection du patrimoine familial","L’éducation religieuse","L’intérêt de l’enfant","L’autorité des parents"]'::jsonb, 2, 'C’est un ensemble de droits et de devoirs ayant pour finalité l’intérêt de l’enfant.', 1),
    ('e7059bc6-98ca-5b16-99e9-928526a6d6c1'::uuid, 'f2852c41-826b-51c1-818c-4994241c5e90'::uuid, 'Jusqu’à quand l’autorité parentale dure-t-elle ?', 'mcq', '["25 ans","12 ans","16 ans","La majorité ou l’émancipation de l’enfant"]'::jsonb, 3, 'Elle appartient aux parents jusqu’à la majorité ou l’émancipation.', 2),
    ('49c9d337-28d1-51ba-838a-456fc47b8e87'::uuid, 'f2852c41-826b-51c1-818c-4994241c5e90'::uuid, 'Après une séparation, l’autorité parentale reste en principe exercée conjointement.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Article 373-2 : la séparation est sans incidence sur les règles de dévolution de l’exercice.', 3),
    ('2a981c11-2592-5a37-a222-9fa67a157113'::uuid, 'f2852c41-826b-51c1-818c-4994241c5e90'::uuid, 'Quelle loi a posé le principe de l’exercice conjoint de l’autorité parentale ?', 'mcq', '["La loi du 17 mai 2013","La loi du 23 mars 2019","La loi du 2 mars 2022","La loi du 4 mars 2002"]'::jsonb, 3, 'La loi du 4 mars 2002 relative à l’autorité parentale a consacré la coparentalité.', 4),
    ('910379d1-7d90-5872-a072-0f7fbd821b49'::uuid, 'f2852c41-826b-51c1-818c-4994241c5e90'::uuid, 'À l’égard des tiers de bonne foi, un parent qui fait seul un acte usuel est réputé…', 'mcq', '["Commettre une faute","Agir en tant que tuteur","Agir sans autorisation","Agir avec l’accord de l’autre parent"]'::jsonb, 3, 'Article 372-2 : présomption d’accord de l’autre parent pour les actes usuels.', 5),
    ('d42e2de6-c347-52e4-98a5-4c7e4fd32cc6'::uuid, 'f2852c41-826b-51c1-818c-4994241c5e90'::uuid, 'Lequel de ces actes est un acte important ?', 'mcq', '["Un rendez-vous chez le coiffeur","Un rendez-vous pour un rhume","Le changement d’établissement scolaire","L’achat de fournitures"]'::jsonb, 2, 'Un changement d’école requiert l’accord des deux parents.', 6),
    ('8dc27541-787d-570f-a24b-a4ecf839a721'::uuid, 'f2852c41-826b-51c1-818c-4994241c5e90'::uuid, 'Que dit l’article 371-1 depuis la loi du 10 juillet 2019 ?', 'mcq', '["L’autorité parentale s’exerce sans violences physiques ou psychologiques","Le droit de correction est maintenu","Les parents peuvent corriger raisonnablement","L’enfant est exclu des décisions"]'::jsonb, 0, 'Les violences éducatives ordinaires sont écartées par la loi du 10 juillet 2019.', 7),
    ('67c84f45-d3d5-57a1-bea2-9e0aa28db9bb'::uuid, 'f2852c41-826b-51c1-818c-4994241c5e90'::uuid, 'La résidence alternée est impossible en droit français.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le juge peut fixer la résidence en alternance ou chez l’un des parents (article 373-2-9).', 8),
    ('701a05d0-4b2a-5c67-bef3-ef0580b39b2f'::uuid, 'f2852c41-826b-51c1-818c-4994241c5e90'::uuid, 'Quel juge ordonne une mesure d’assistance éducative lorsque l’enfant est en danger ?', 'mcq', '["Le juge de l’exécution","Le juge des libertés","Le juge d’instruction","Le juge des enfants"]'::jsonb, 3, 'Article 375 : le juge des enfants intervient pour les mineurs en danger.', 9),
    ('b9794ee2-6ffa-5691-bc50-944ace453aa0'::uuid, 'f2852c41-826b-51c1-818c-4994241c5e90'::uuid, 'La contribution à l’entretien et à l’éducation de l’enfant peut-elle survivre à sa majorité ?', 'mcq', '["Seulement si l’enfant est étudiant boursier","Jamais","Oui, tant que l’enfant n’est pas en mesure de subvenir à ses besoins","Seulement jusqu’à 21 ans"]'::jsonb, 2, 'L’obligation subsiste après la majorité tant que l’enfant n’est pas autonome (article 371-2).', 10),
    ('61020a7d-24cd-514b-ba81-8eafcc071fb6'::uuid, 'f2852c41-826b-51c1-818c-4994241c5e90'::uuid, 'Dans quel cas le retrait de l’autorité parentale peut-il être prononcé ?', 'mcq', '["En cas de divorce","En cas de simple désaccord éducatif","En cas de condamnation pour crime ou délit commis sur l’enfant","En cas de déménagement"]'::jsonb, 2, 'Les articles 378 et suivants prévoient le retrait pour des faits graves.', 11),
    ('47009160-a62b-5985-85d5-0e3c1224911c'::uuid, 'f2852c41-826b-51c1-818c-4994241c5e90'::uuid, 'Que gèrent les parents au titre de l’administration légale ?', 'mcq', '["Les biens du ménage","Les biens de leurs propres parents","Les biens de l’État","Les biens de l’enfant mineur"]'::jsonb, 3, 'Les parents administrent le patrimoine de leur enfant mineur, avec contrôle du juge des tutelles pour les actes graves.', 12)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('droit-civil');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('droit-civil')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 608 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 608 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
